INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774921932068', 'A large e-commerce company needs to forecast product demand for thousands of items daily. The demand patterns are complex, exhibiting seasonality and trends, and vary significantly across products. The company requires a scalable, cost-effective solution that can handle multivariate time series data and provide accurate forecasts with minimal infrastructure management. Which SageMaker built-in algorithm is best suited for this task?', '["Amazon SageMaker XGBoost, due to its high performance on tabular data and ability to handle complex relationships.","Amazon SageMaker Linear Learner, for its simplicity and interpretability in regression tasks.","Amazon SageMaker k-means, for clustering similar products based on their demand patterns.","Amazon SageMaker DeepAR, designed specifically for probabilistic forecasting of time series data."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most appropriate choice. Amazon SageMaker DeepAR is a supervised learning algorithm for forecasting scalar (one-dimensional) time series using recurrent neural networks. It is particularly effective for datasets with many related time series, allowing the model to learn common patterns across them, which is ideal for forecasting thousands of products with complex patterns. It offers scalable and accurate probabilistic forecasts. Option A (incorrect) is Amazon SageMaker XGBoost, which is excellent for tabular data classification and regression but not specifically optimized for time series forecasting with complex temporal dependencies and seasonality. Option B (incorrect) is Amazon SageMaker Linear Learner, a linear model that would struggle with the complexity and non-linear patterns of demand forecasting. Option C (incorrect) is Amazon SageMaker k-means, an unsupervised clustering algorithm, which is not designed for forecasting future values.', 15, 'm_15_1', 8, NULL, NULL),
  ('mock_14_all_1774921932068', 'A marketing analytics team needs to build a model to predict whether a customer will click on a promotional advertisement based on their browsing history, demographics, and past purchase behavior. The dataset is large and consists primarily of structured, tabular data. The team requires a highly accurate and robust binary classification model that can handle non-linear relationships and feature interactions. Which SageMaker built-in algorithm should they choose?', '["Amazon SageMaker XGBoost, known for its high performance, speed, and ability to handle tabular data effectively.","Amazon SageMaker k-means, for segmenting customers into different groups based on their attributes.","Amazon SageMaker Linear Learner, for its simplicity and interpretability in classification tasks.","Amazon SageMaker BlazingText, for processing and classifying textual data related to ad content."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable choice. Amazon SageMaker XGBoost is a highly efficient, flexible, and portable gradient boosting library that is widely recognized for its performance on structured/tabular data. It excels at binary classification problems, can handle non-linear relationships and feature interactions, and is highly scalable, making it ideal for a large marketing dataset. Option B (incorrect) is Amazon SageMaker k-means, an unsupervised algorithm used for clustering, not for supervised binary classification. Option C (incorrect) is Amazon SageMaker Linear Learner, which is a linear model and might not capture the complex non-linear relationships often present in customer behavior data as effectively as XGBoost. Option D (incorrect) is Amazon SageMaker BlazingText, which is designed for text classification and word embeddings, not for tabular data classification.', 15, 'm_15_1', 9, NULL, NULL),
  ('mock_14_all_1774921932068', 'A content moderation team needs to automatically categorize user-generated text comments as ''spam'', ''hate speech'', or ''neutral''. The team has a large labeled dataset of comments. They require a solution that can quickly train a text classification model with minimal code and leverage pre-trained word embeddings for better performance. Which SageMaker built-in algorithm is best suited for this task?', '["Amazon SageMaker Linear Learner, for its ability to perform multi-class classification on text features.","Amazon SageMaker BlazingText, which supports text classification and can utilize FastText word embeddings.","Amazon SageMaker Object Detection, for identifying specific keywords or phrases within the text comments.","Amazon SageMaker DeepAR, for analyzing the temporal sequence of words in comments to predict categories."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate choice. Amazon SageMaker BlazingText is a highly optimized, scalable algorithm for text classification and word embeddings. It can efficiently train models for multi-class text classification tasks and supports the use of FastText word embeddings, which are pre-trained and can significantly improve performance, especially with minimal code. Option A (incorrect) is Amazon SageMaker Linear Learner, which is a linear model and generally less effective for complex text classification tasks compared to BlazingText''s neural network approach. Option C (incorrect) is Amazon SageMaker Object Detection, which is designed for computer vision tasks, not text processing. Option D (incorrect) is Amazon SageMaker DeepAR, which is for time series forecasting, not text classification.', 15, 'm_15_1', 10, NULL, NULL),
  ('mock_14_all_1774921932068', 'A manufacturing company wants to automate quality control by identifying defects in product images on an assembly line. They have a limited dataset of labeled images with defects. The team needs to rapidly develop and deploy an object detection model, leveraging existing knowledge from pre-trained models to achieve high accuracy with minimal training data and development effort. Which SageMaker feature or approach should they prioritize?', '["Develop a custom object detection algorithm from scratch using a TensorFlow script mode, then train it on SageMaker.","Utilize Amazon SageMaker XGBoost to classify images based on extracted features, avoiding direct object detection.","Leverage SageMaker JumpStart to find and fine-tune a pre-trained object detection model with their specific defect images.","Employ Amazon SageMaker k-means to cluster similar defect types in images for unsupervised anomaly detection."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most efficient and effective approach. SageMaker JumpStart provides a hub for pre-trained models, including object detection models, which can be fine-tuned with a company''s specific dataset. This approach leverages transfer learning, significantly reducing the need for large datasets and extensive development effort to achieve high accuracy, directly addressing the requirement for rapid development with limited data. Option A (incorrect) suggests building a custom algorithm from scratch, which is an anti-pattern (ap-2.1-001) as it requires significant development effort, time, and expertise, especially when pre-built solutions exist. Option B (incorrect) proposes using SageMaker XGBoost, which is suitable for tabular data and not designed for object detection in images. Option D (incorrect) suggests Amazon SageMaker k-means, an unsupervised clustering algorithm, which is not suitable for supervised object detection tasks.', 15, 'm_15_1', 11, NULL, NULL),
  ('mock_14_all_1774921932068', 'A retail company wants to understand customer segments to tailor marketing campaigns. They have a large dataset of customer demographics, purchase history, and browsing behavior, but no predefined labels for customer groups. The data science team needs to discover natural groupings within this data to identify distinct customer segments. Which SageMaker built-in algorithm is most appropriate for this unsupervised learning task?', '["Amazon SageMaker Linear Learner, to predict customer lifetime value based on their attributes.","Amazon SageMaker XGBoost, to classify customers into predefined segments based on historical data.","Amazon SageMaker DeepAR, to forecast future customer behavior for each segment.","Amazon SageMaker k-means, to cluster customers into distinct groups based on feature similarity."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most appropriate choice. Amazon SageMaker k-means is an unsupervised learning algorithm used for clustering. It is specifically designed to discover natural groupings (clusters) within a dataset when there are no predefined labels, which perfectly matches the requirement of identifying distinct customer segments based on their attributes. Option A (incorrect) is Amazon SageMaker Linear Learner, a supervised algorithm for regression or classification, not unsupervised clustering. Option B (incorrect) is Amazon SageMaker XGBoost, a supervised algorithm for classification or regression, which would require predefined customer segments. Option C (incorrect) is Amazon SageMaker DeepAR, which is for time series forecasting, not customer segmentation.', 15, 'm_15_1', 12, NULL, NULL),
  ('mock_14_all_1774921932068', 'A research team is developing a novel deep learning model for medical image analysis. They have implemented a custom neural network architecture using PyTorch and require full control over the training loop, custom loss functions, and specific data augmentation techniques. They need to train this model on Amazon SageMaker, leveraging its managed infrastructure while maintaining flexibility for their custom code. Which SageMaker approach should they use?', '["Utilize SageMaker''s built-in XGBoost algorithm, adapting their medical image data to its tabular input format.","Run the PyTorch model training script directly on an Amazon EC2 instance to maintain full control.","Use SageMaker''s PyTorch script mode, providing their custom training script and dependencies.","Deploy a pre-trained model from SageMaker JumpStart and fine-tune it with their medical image data."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the ideal approach. SageMaker''s PyTorch script mode allows users to bring their own PyTorch training scripts and dependencies, providing full flexibility and control over the training logic, custom loss functions, and data augmentation techniques. SageMaker manages the underlying infrastructure, instance provisioning, and scaling, combining the benefits of managed services with custom code flexibility. Option A (incorrect) suggests using SageMaker''s built-in XGBoost algorithm, which is not suitable for deep learning on image data and would require significant data transformation, losing the benefits of their custom PyTorch model. Option B (incorrect) involves running on a raw Amazon EC2 instance, which would require manual setup, configuration, and management of the entire training environment, increasing operational overhead significantly compared to SageMaker''s managed service. Option D (incorrect) uses SageMaker JumpStart, which is great for leveraging pre-trained models, but the team specifically requires full control over a novel custom architecture, making JumpStart less suitable for this specific requirement.', 15, 'm_15_1', 13, NULL, NULL);

