INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774921932068', 'A data science team is developing a new image classification model. They have identified several hyperparameters that significantly impact model performance, such as learning rate, batch size, and optimizer choice. Manually tuning these hyperparameters is time-consuming and inefficient. The team needs to automatically find the optimal combination of hyperparameters to achieve the best model performance with the LEAST manual effort. Which SageMaker feature should they use?', '["Implement SageMaker Experiments to log all training metrics and manually compare the results of different hyperparameter settings.","Configure SageMaker Training Jobs to run multiple training instances in parallel, each with a different fixed set of hyperparameters.","Utilize SageMaker Automatic Model Tuning (AMT) to automate the search for the best hyperparameter configuration.","Develop a custom script to perform a grid search locally on a single Amazon EC2 instance before migrating to SageMaker."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective solution. Amazon SageMaker Automatic Model Tuning (AMT), also known as Hyperparameter Optimization (HPO), automates the process of finding the best version of a model by running many training jobs with different hyperparameter combinations. It uses advanced techniques like Bayesian optimization to efficiently search the hyperparameter space, significantly reducing manual effort and improving model performance. Option A (incorrect) uses SageMaker Experiments for logging, which is useful for tracking but still requires manual analysis and decision-making for tuning. Option B (incorrect) describes a manual parallel grid search, which is less efficient than AMT''s intelligent search strategies and still requires manual configuration of each hyperparameter set. Option D (incorrect) suggests a local grid search, which is not scalable, requires manual setup, and does not leverage SageMaker''s managed tuning capabilities.', 15, 'm_15_2', 14, NULL, NULL),
  ('mock_14_all_1774921932068', 'A startup is training a deep learning model that requires several hours to converge. The training jobs are not mission-critical and can tolerate interruptions. The team needs to significantly reduce the cost of these long-running training jobs without compromising the ability to complete the training. Which SageMaker feature should they leverage?', '["Use SageMaker Training Jobs with on-demand instances, as they provide consistent performance.","Implement SageMaker Automatic Model Tuning (AMT) to optimize hyperparameters, which indirectly reduces training time and cost.","Utilize SageMaker Experiments to track resource utilization and identify opportunities for cost savings.","Configure SageMaker Managed Spot Training with checkpointing enabled to use EC2 Spot Instances."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective solution for reducing training costs for non-critical, long-running jobs. SageMaker Managed Spot Training allows training jobs to use Amazon EC2 Spot Instances, which can reduce costs by up to 90% compared to on-demand instances. With checkpointing enabled, if a Spot Instance is interrupted, the training job can resume from the last saved checkpoint, minimizing lost work and ensuring eventual completion. This directly addresses the anti-pattern (ap-2.2-002) of not using Spot Instances for such jobs. Option A (incorrect) uses on-demand instances, which are reliable but significantly more expensive, contradicting the cost reduction goal. Option B (incorrect) uses SageMaker AMT for hyperparameter optimization, which aims to improve model performance and potentially reduce overall training time, but it''s not the primary mechanism for direct cost reduction through instance pricing. Option C (incorrect) uses SageMaker Experiments for tracking, which provides insights but does not directly implement cost-saving measures like Spot Instances.', 15, 'm_15_2', 15, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data science team is iteratively developing and training multiple versions of a machine learning model. They need a systematic way to organize, track, and compare the performance metrics, hyperparameters, and artifacts (like model weights) from each training run. This is essential for reproducibility and understanding the impact of different experimental choices. Which AWS service or feature should they use?', '["Amazon SageMaker Experiments, to manage and track all aspects of their ML development lifecycle.","Amazon SageMaker Automatic Model Tuning (AMT), to automatically log the best performing model''s details.","Amazon CloudWatch Logs, to store the raw output logs from each SageMaker Training Job.","Amazon S3, to manually store model artifacts and a spreadsheet for tracking hyperparameters."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution. Amazon SageMaker Experiments provides a comprehensive way to organize, track, compare, and evaluate machine learning experiments. It allows data scientists to automatically log input parameters, configurations, metrics, and artifacts for each training run, making it easy to reproduce results and understand the impact of different choices. Option B (incorrect) is SageMaker Automatic Model Tuning (AMT), which is for hyperparameter optimization, not for general experiment tracking across different model versions or manual runs. Option C (incorrect) uses Amazon CloudWatch Logs, which stores raw logs but does not provide the structured tracking, comparison, and artifact management capabilities of SageMaker Experiments. Option D (incorrect) describes a manual approach using Amazon S3 and a spreadsheet, which is inefficient, prone to errors, and lacks the automation and rich visualization features of SageMaker Experiments.', 15, 'm_15_2', 16, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data scientist is using SageMaker Automatic Model Tuning (AMT) to optimize a deep learning model. They have defined a wide range for hyperparameters like learning rate (0.0001 to 1.0) and batch size (16 to 256) but are observing slow convergence and suboptimal results after many trials. The team needs to improve the efficiency of hyperparameter search to find better configurations within a limited budget. Which adjustment to their AMT strategy should they make?', '["Switch from Bayesian optimization to a random search strategy to cover the search space more broadly.","Increase the number of training instances per trial to speed up individual training jobs, regardless of search strategy.","Narrow the hyperparameter search ranges based on domain knowledge and use Bayesian optimization for efficient exploration.","Increase the maximum number of training jobs in AMT to ensure every possible combination within the wide range is tested."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) directly addresses the anti-pattern (ap-2.2-001) of running HPO with too wide a search space and few trials. Narrowing the search ranges based on domain knowledge (e.g., typical effective learning rates) and leveraging Bayesian optimization (which is the default and recommended strategy for SageMaker AMT) allows for a more efficient and targeted exploration of the hyperparameter space, leading to faster convergence to optimal configurations within a limited budget. Option A (incorrect) suggests switching to random search, which is less efficient than Bayesian optimization for finding optimal values, especially when the search space is already too wide. Option B (incorrect) focuses on speeding up individual trials, which doesn''t address the inefficiency of the search strategy itself. Option D (incorrect) suggests increasing the number of training jobs to test every combination, which is computationally expensive and inefficient for wide ranges, especially with grid search, and contradicts the goal of efficient search within a limited budget.', 15, 'm_15_2', 17, NULL, NULL),
  ('mock_14_all_1774921932068', 'A deep learning engineer is training a complex neural network for natural language processing. The model is showing signs of overfitting, achieving very high accuracy on the training data but poor performance on the validation set. They want to prevent the model from memorizing the training data without significantly altering the model''s architecture or collecting more data. Which regularization technique should they implement during training?', '["Increase the size of the training dataset by generating synthetic data to provide more diverse examples.","Implement L1 and L2 regularization (weight decay) to penalize large weights in the neural network.","Reduce the number of layers and neurons in the neural network to simplify the model''s capacity.","Use SageMaker Clarify to analyze feature importance and remove less relevant features from the input."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is a direct and effective regularization technique to combat overfitting. L1 and L2 regularization (also known as weight decay) add a penalty to the loss function based on the magnitude of the model''s weights, encouraging the model to learn simpler, more generalized patterns and preventing it from memorizing the training data. This can be implemented without altering the model architecture significantly. Option A (incorrect) suggests generating synthetic data, which is a data augmentation strategy, not a regularization technique, and goes against the constraint of not collecting more data (anti-pattern ap-2.3-001). Option C (incorrect) involves manually reducing model complexity, which is a structural change and can be time-consuming to find the right balance. Option D (incorrect) uses SageMaker Clarify for feature importance, which is for explainability and bias detection, not a direct method to prevent overfitting during training.', 15, 'm_15_2', 18, NULL, NULL),
  ('mock_14_all_1774921932068', 'A computer vision team is training a large image classification model on a dataset of millions of images. The training process is computationally intensive, requiring significant GPU resources. They need to ensure the training jobs run with the HIGHEST possible performance and throughput to minimize the overall training time. Which type of Amazon EC2 instance should they select for their SageMaker Training Jobs?', '["Amazon EC2 P4d instances, which are optimized for deep learning with powerful NVIDIA A100 GPUs.","Amazon EC2 M5 instances, which are general-purpose instances suitable for most workloads.","Amazon EC2 T3 instances, which are burstable performance instances for low-cost development.","Amazon EC2 C5 instances, which are compute-optimized instances for CPU-intensive tasks."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate choice for achieving the highest performance for large image classification models. Amazon EC2 P4d instances are specifically designed for high-performance deep learning and machine learning workloads, featuring the latest generation NVIDIA A100 Tensor Core GPUs, high-bandwidth networking, and fast local storage. These instances provide the highest GPU compute power and throughput available for training. Option B (incorrect) are Amazon EC2 M5 instances, which are general-purpose and not optimized for GPU-intensive deep learning. Option C (incorrect) are Amazon EC2 T3 instances, which are burstable and suitable for development or small workloads, not for high-performance, large-scale training. Option D (incorrect) are Amazon EC2 C5 instances, which are compute-optimized but rely on CPUs, making them unsuitable for GPU-accelerated deep learning tasks.', 15, 'm_15_2', 19, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 19
WHERE id = 'mock_14_all_1774921932068';

COMMIT;


