-- Module: m_16_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774921932068', 'A company needs to process millions of records daily for sentiment analysis. The processing is not time-sensitive and can tolerate latency of several hours. They require the MOST cost-effective solution for this large-scale, non-interactive inference workload.', '["Deploy the model to an Amazon SageMaker real-time endpoint with auto-scaling configured.","Use Amazon SageMaker Serverless Inference for the model to handle variable batch sizes.","Implement Amazon SageMaker Batch Transform to process the data in large, asynchronous jobs.","Set up an Amazon SageMaker Asynchronous Inference endpoint to handle the large payloads."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most cost-effective for large-scale, non-time-sensitive inference. Amazon SageMaker Batch Transform spins up ephemeral compute resources, processes the entire dataset, and then terminates, paying only for the duration of the job. Option A (incorrect) involves persistent instances for real-time inference, which is significantly more costly for non-interactive batch workloads, representing the anti-pattern of using real-time inference for large batch scoring jobs. Option B (incorrect) is designed for low-volume, infrequent real-time inference and would be expensive for processing millions of records daily. Option D (incorrect) is suitable for large individual payloads with some latency tolerance, but for millions of records in a batch, Batch Transform is more efficient and cost-effective.', 16, 'm_16_1', 9, NULL, NULL),
  ('mock_14_all_1774921932068', 'A web application serves a machine learning model that experiences highly variable traffic patterns, with unpredictable spikes and idle periods. The company needs to ensure low latency during peak times while minimizing costs during off-peak hours for real-time inference.', '["Deploy the model to a fixed-capacity Amazon SageMaker real-time endpoint.","Use Amazon SageMaker real-time endpoint with Application Auto Scaling configured based on invocation metrics.","Implement Amazon SageMaker Serverless Inference to handle the variable traffic.","Utilize Amazon SageMaker Asynchronous Inference for the model to manage large request queues."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the optimal solution. An Amazon SageMaker real-time endpoint provides low-latency inference, and Application Auto Scaling dynamically adjusts the number of instances based on traffic, ensuring capacity during peaks and cost savings during idle periods. Option A (incorrect) would lead to either over-provisioning and high costs during low traffic or under-provisioning and high latency during spikes, representing the anti-pattern of not configuring endpoint auto-scaling for variable inference traffic. Option C (incorrect) is suitable for low, infrequent traffic but may not consistently meet low-latency requirements during unpredictable spikes due to cold starts. Option D (incorrect) is designed for large payloads and asynchronous processing, not for real-time web application inference.', 16, 'm_16_1', 10, NULL, NULL),
  ('mock_14_all_1774921932068', 'A startup has developed a computer vision model that needs to be deployed for real-time inference. They anticipate low, infrequent traffic but require a highly responsive API when requests do arrive, and they want to pay only for actual usage, minimizing idle costs.', '["Deploy the model to an Amazon SageMaker real-time endpoint with a minimum of one instance.","Utilize Amazon SageMaker Serverless Inference for the model endpoint.","Implement Amazon SageMaker Batch Transform for processing individual inference requests.","Set up an Amazon SageMaker Asynchronous Inference endpoint to handle the requests."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is ideal for this scenario. Amazon SageMaker Serverless Inference automatically scales compute resources based on traffic, spinning down to zero instances during idle periods, so you only pay for the duration of inference requests and the amount of data processed. This minimizes idle costs while providing a responsive API. Option A (incorrect) would incur costs for the minimum instance even during idle periods, failing the ''pay only for actual usage'' constraint. Option C (incorrect) is for batch processing and not suitable for real-time, responsive API calls. Option D (incorrect) is designed for large payloads and asynchronous processing, which does not fit the ''highly responsive API'' requirement for infrequent, real-time requests.', 16, 'm_16_1', 11, NULL, NULL),
  ('mock_14_all_1774921932068', 'A financial institution needs to deploy a fraud detection model that processes large payloads (e.g., entire transaction histories) and can tolerate a few minutes of processing time. They require a fully managed solution that handles queuing and retries automatically for these requests.', '["Deploy the model to an Amazon SageMaker real-time endpoint.","Use Amazon SageMaker Batch Transform for individual large payloads.","Implement Amazon SageMaker Serverless Inference for the model.","Set up an Amazon SageMaker Asynchronous Inference endpoint."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is designed for this use case. Amazon SageMaker Asynchronous Inference is ideal for models with large payload sizes, long processing times, and requests that can tolerate a few minutes of latency. It automatically handles request queuing, retries, and error handling, providing a fully managed solution. Option A (incorrect) is unsuitable for large payloads as real-time endpoints have payload size limits and timeouts, which would be exceeded. Option B (incorrect) is for processing large datasets in batches, not individual large payloads with immediate (though tolerant) feedback requirements. Option C (incorrect) has payload size limits and is optimized for low, infrequent real-time requests, not large, long-running ones.', 16, 'm_16_1', 12, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company is deploying multiple small, independent machine learning models that share the same instance type and require similar compute resources. They want to optimize costs and resource utilization by hosting these models on a single endpoint for real-time inference.', '["Deploy each model to its own dedicated Amazon SageMaker real-time endpoint.","Deploy all models to a single Amazon SageMaker Multi-Model Endpoint.","Use Amazon SageMaker Inference Pipelines to chain the models together.","Process all inference requests using Amazon SageMaker Batch Transform."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is designed for this scenario. An Amazon SageMaker Multi-Model Endpoint allows you to host multiple models on a single endpoint instance, dynamically loading and unloading models from memory as needed. This significantly optimizes costs and resource utilization by sharing the underlying compute infrastructure. Option A (incorrect) would incur higher costs as each model would require its own dedicated endpoint instance. Option C (incorrect) is used for chaining multiple models or pre-processing steps sequentially for a single inference request, not for hosting independent models. Option D (incorrect) is for batch processing and not suitable for real-time inference.', 16, 'm_16_1', 13, NULL, NULL),
  ('mock_14_all_1774921932068', 'A manufacturing plant needs to deploy a deep learning model to an edge device with limited compute resources. The model needs to be optimized for specific hardware accelerators to achieve the highest possible inference performance and lowest latency on the device.', '["Deploy the original, unoptimized model directly to the edge device.","Apply general model quantization techniques to reduce model size.","Compile the model with Amazon SageMaker Neo for the target hardware accelerator.","Use model pruning to remove redundant connections and reduce complexity."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is specifically designed for this scenario. Amazon SageMaker Neo compiles ML models to optimize them for specific hardware accelerators and edge devices, resulting in significant improvements in inference performance and reduced latency. Option A (incorrect) would result in poor performance and potentially exceed the limited resources of the edge device. Option B (incorrect) and Option D (incorrect) are general model optimization techniques that reduce model size or complexity but do not specifically compile the model for hardware accelerators to achieve the highest possible performance on a target device.', 16, 'm_16_1', 14, NULL, NULL),
  ('mock_14_all_1774921932068', 'A large e-commerce platform needs to serve a recommendation model that experiences predictable daily peaks and troughs in traffic. They want to ensure sufficient capacity during peak hours while avoiding over-provisioning during low traffic, aiming for the MOST cost-effective real-time solution.', '["Deploy a fixed-size Amazon SageMaker real-time endpoint with enough instances for peak traffic.","Configure an Amazon SageMaker real-time endpoint with Application Auto Scaling based on invocation metrics.","Use Amazon SageMaker Serverless Inference for the model to handle the variable traffic patterns.","Implement Amazon SageMaker Batch Transform to process recommendation requests at scheduled intervals."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective real-time solution for predictable variable traffic. Application Auto Scaling for Amazon SageMaker real-time endpoints automatically adjusts the number of instances based on actual invocation metrics, ensuring optimal capacity during peaks and scaling down during troughs to minimize costs. Option A (incorrect) would lead to significant over-provisioning and wasted costs during low traffic periods, representing the anti-pattern of not configuring endpoint auto-scaling for variable inference traffic. Option C (incorrect) is generally more expensive than auto-scaled real-time endpoints for predictable, high-volume traffic patterns due to potential cold starts and different pricing models. Option D (incorrect) is for batch processing and cannot provide real-time recommendations.', 16, 'm_16_1', 15, NULL, NULL);

