INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774921932068', 'An ML team needs to deploy a new version of a critical recommendation model to a SageMaker endpoint. To minimize the risk of production issues and validate the new model''s performance in a controlled manner, they want to gradually shift traffic to the new model while monitoring its performance against the old one.', '["Perform a blue/green deployment by creating a new endpoint and then switching all traffic at once.","Implement a canary release strategy by gradually shifting endpoint traffic to the new model version.","Directly update the existing SageMaker endpoint with the new model, immediately routing 100% of traffic.","Use A/B testing to compare the new model''s business metrics against the old one without traffic shifting."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes a canary release, which is ideal for minimizing risk during model deployments. It allows for a gradual rollout of the new model, enabling real-time performance monitoring and quick rollback if issues arise, without impacting all users. Option A (incorrect) switches all traffic at once, which is a blue/green deployment. While it offers zero downtime and easy rollback, it doesn''t allow for gradual validation, thus carrying higher risk than a canary release. Option C (incorrect) is an anti-pattern as it deploys a new model version directly to 100% traffic without canary testing, risking production outages if the new model regresses. Option D (incorrect) is primarily for evaluating business impact rather than a deployment strategy for risk mitigation during model rollout.', 16, 'm_16_3', 16, NULL, NULL),
  ('mock_14_all_1774921932068', 'A retail company''s recommendation model experiences performance degradation over time due to changes in customer behavior. They want to automatically retrain the model when its performance (e.g., accuracy) drops below a predefined threshold in production, ensuring model freshness.', '["Implement a monitoring solution that detects performance degradation and triggers a SageMaker Pipeline via Amazon EventBridge.","Schedule the SageMaker Pipeline to retrain the model every month, regardless of performance.","Configure an Amazon S3 event trigger to start retraining whenever new data is added to the training bucket.","Rely on manual intervention by data scientists to periodically review model performance and initiate retraining."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides an automated, event-driven solution for retraining based on performance degradation. A monitoring system (e.g., CloudWatch metrics) can detect the threshold breach and emit an event, which Amazon EventBridge can then use to trigger the SageMaker Pipeline. Option B (incorrect) is a scheduled approach that might miss critical performance drops between scheduled runs or retrain unnecessarily. Option C (incorrect) triggers retraining based on data availability, not model performance, which doesn''t address the specific requirement. Option D (incorrect) is a manual process and does not meet the requirement for automated retraining.', 16, 'm_16_3', 17, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data science team has built a SageMaker Pipeline for continuous training. They want to ensure that the pipeline runs automatically every week to retrain the model with the latest data, even if no new data arrives, to maintain model freshness.', '["Use Amazon EventBridge to create a scheduled rule that triggers the SageMaker Pipeline weekly.","Configure an Amazon S3 event trigger to start the pipeline whenever new data is added to the training bucket.","Manually trigger the SageMaker Pipeline from the AWS Management Console once a week.","Implement a data drift monitor to trigger the pipeline only when significant data drift is detected."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution for scheduled retraining. Amazon EventBridge allows you to define cron-like schedules that can reliably trigger a SageMaker Pipeline at specified intervals, ensuring the model is retrained weekly as required. Option B (incorrect) would only trigger the pipeline when new data arrives in S3, not on a fixed weekly schedule. Option C (incorrect) is a manual process and does not meet the requirement for automated execution. Option D (incorrect) triggers based on data drift, which is a different trigger strategy and doesn''t guarantee a weekly retraining regardless of drift.', 16, 'm_16_3', 18, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company needs to update a production SageMaker endpoint with a new model version. They want to ensure zero downtime and have an immediate rollback option in case the new model performs poorly, without gradually shifting traffic.', '["Perform a blue/green deployment by creating a new endpoint and then switching traffic instantly.","Implement a canary release strategy by gradually shifting endpoint traffic to the new model.","Directly update the existing SageMaker endpoint with the new model, risking downtime.","Use A/B testing to compare the new model''s performance with the old one over an extended period."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) describes a blue/green deployment, which is perfect for zero-downtime updates and immediate rollback. A new ''green'' endpoint is deployed with the new model, and once validated, traffic is switched instantly from the ''blue'' (old) endpoint to the ''green'' endpoint. If issues arise, traffic can be immediately switched back to the ''blue'' endpoint. Option B (incorrect) involves a gradual traffic shift, which is not an ''immediate rollback'' strategy, though it minimizes risk. Option C (incorrect) directly updates the endpoint, which can cause downtime or service disruption during the update process and lacks an immediate rollback mechanism. Option D (incorrect) is for comparing model effectiveness over time, not for a deployment strategy focused on zero downtime and immediate rollback.', 16, 'm_16_3', 19, NULL, NULL),
  ('mock_14_all_1774921932068', 'An ML engineering team wants to automate the entire process of model training, evaluation, and conditional registration into a model registry. They need to define a workflow where specific steps only execute if certain conditions (e.g., model accuracy threshold) are met.', '["Use AWS CodePipeline to orchestrate the workflow with custom Lambda functions for conditional logic.","Implement the entire workflow using Amazon SageMaker Pipelines with conditional steps.","Orchestrate the workflow with AWS Step Functions, calling SageMaker jobs as needed.","Write a single Python script to run all steps sequentially and manually check conditions."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable and native solution for this requirement. Amazon SageMaker Pipelines allows you to define complex ML workflows with conditional steps, enabling specific actions (like model registration) to occur only if predefined criteria (e.g., model accuracy) are met. Option A (incorrect) would require significant custom development to implement conditional logic within Lambda functions and integrate with SageMaker, increasing complexity and operational overhead. Option C (incorrect) can orchestrate workflows with conditions, but SageMaker Pipelines is purpose-built for ML workflows and offers deeper integration with SageMaker components, making it more efficient for this specific use case. Option D (incorrect) is a manual and non-scalable approach that lacks automation and governance features.', 16, 'm_16_3', 20, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data scientist has developed a new model that significantly improves accuracy. Before deploying it to production, the team wants to run a full suite of integration tests and ensure the model meets all quality gates within an automated pipeline.', '["Manually run integration tests on a staging environment before deployment.","Integrate AWS CodeBuild into an AWS CodePipeline to run integration tests and validate the model before deployment.","Use Amazon SageMaker Processing Jobs to run the integration tests.","Deploy the model directly to production and monitor its performance in real-time."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate solution for automated integration testing within a CI/CD pipeline. AWS CodePipeline orchestrates the entire process, and AWS CodeBuild can execute custom test scripts to run a full suite of integration tests and enforce quality gates before the model proceeds to deployment. Option A (incorrect) is a manual process and does not meet the requirement for an automated pipeline. Option C (incorrect) is primarily for data processing and feature engineering tasks, not for orchestrating integration tests within a CI/CD flow. Option D (incorrect) is a high-risk approach that bypasses quality gates and could lead to production issues, representing an anti-pattern of deploying without proper validation.', 16, 'm_16_3', 21, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company wants to automate the retraining of their fraud detection model whenever new training data becomes available in an Amazon S3 bucket. They need an event-driven mechanism to trigger their SageMaker Pipeline for continuous training.', '["Configure an Amazon EventBridge rule to detect S3 object creation events and trigger the SageMaker Pipeline.","Create an AWS Lambda function that periodically polls the S3 bucket for new data and triggers the pipeline.","Manually trigger the SageMaker Pipeline from the AWS Management Console whenever new data is uploaded.","Set up a cron job on an Amazon EC2 instance to check S3 for new data and then invoke the pipeline."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a fully managed, event-driven solution. Amazon EventBridge can directly integrate with Amazon S3 to detect object creation events and then trigger a SageMaker Pipeline, automating the retraining process efficiently. Option B (incorrect) introduces operational overhead and costs for the Lambda function and polling mechanism, which is less efficient than a direct event-driven trigger. Option C (incorrect) is a manual process and does not meet the automation requirement. Option D (incorrect) requires managing an EC2 instance and custom scripting, increasing operational overhead and complexity compared to EventBridge.', 16, 'm_16_3', 22, NULL, NULL);

