INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774921932068', 'A data science team is deploying a new fraud detection model on Amazon SageMaker. The model needs to handle varying inference loads, with peak traffic during business hours and significantly lower traffic overnight. The team wants to minimize inference costs while ensuring the model remains highly available and responsive during peak times. Which solution BEST meets these requirements?', '["Configure the Amazon SageMaker endpoint with auto-scaling policies based on target utilization and use a single instance type.","Deploy the Amazon SageMaker endpoint on a fixed number of ml.m5.large instances and manually scale up/down as needed.","Use Amazon SageMaker Batch Transform for all inference requests to process data in scheduled batches.","Set up a SageMaker endpoint with a large, expensive instance type to handle peak load, and leave it running 24/7."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective and operationally efficient solution. Amazon SageMaker auto-scaling automatically adjusts the number of instances based on metrics like `TargetUtilization` or `InvocationsPerInstance`, ensuring that resources are scaled up during peak demand and scaled down during low demand, thereby minimizing costs while maintaining availability and responsiveness. Option B (incorrect) involves manual scaling, which increases operational overhead and can lead to over-provisioning (higher costs) or under-provisioning (performance issues) if not managed perfectly. Option C (incorrect) is suitable for batch processing, not for real-time inference that requires immediate responses. Option D (incorrect) would lead to significant over-provisioning and high costs during off-peak hours, directly violating the goal of minimizing inference costs.', 17, 'm_17_2', 1, NULL, NULL),
  ('mock_14_all_1774921932068', 'A machine learning engineer needs to monitor the operational health of several Amazon SageMaker inference endpoints. They are particularly concerned about high latency, low throughput, and errors that might indicate infrastructure issues. They need a solution that provides real-time visibility and allows for custom dashboards. Which AWS service should they use for this monitoring?', '["AWS CloudTrail to log all API calls related to SageMaker endpoints and analyze logs for errors.","Amazon CloudWatch to collect and visualize standard metrics like `ModelLatency`, `Invocations`, and `InvocationErrors`.","Amazon SageMaker Model Monitor to detect data and model quality drift in real-time.","AWS Config to track changes to SageMaker endpoint configurations and ensure compliance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate service for monitoring operational health metrics like latency, throughput, and errors for Amazon SageMaker endpoints. Amazon CloudWatch automatically collects these standard metrics (`ModelLatency`, `Invocations`, `InvocationErrors`) and allows users to create custom dashboards and set alarms for real-time visibility and alerts. Option A (incorrect) is used for auditing API calls and tracking changes, not for real-time performance monitoring. Option C (incorrect) is specifically designed for detecting data and model quality drift, not for infrastructure-level operational metrics like latency or invocation errors. Option D (incorrect) is for assessing, auditing, and evaluating the configurations of AWS resources, not for real-time performance monitoring.', 17, 'm_17_2', 2, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company is running multiple Amazon SageMaker training jobs daily, but recent cost reports show that some jobs are consistently underutilizing their allocated GPU instances. The ML engineering team wants to identify opportunities to reduce training costs by selecting more appropriate instance types. Which AWS service or feature can help them right-size their SageMaker training instances MOST effectively?', '["AWS Cost Explorer to analyze historical spending patterns and identify high-cost training jobs.","Amazon CloudWatch metrics for CPU/GPU utilization during training jobs to inform instance type selection.","AWS Compute Optimizer to recommend optimal EC2 instance types for SageMaker training jobs.","Amazon SageMaker Inference Recommender to suggest optimal instance types for inference endpoints."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most direct and effective way to right-size SageMaker training instances. By monitoring Amazon CloudWatch metrics such as CPU and GPU utilization during training jobs, the team can identify instances that are consistently underutilized and choose smaller or less powerful instance types for future runs, directly reducing costs. Option A (incorrect) can identify where costs are high but doesn''t provide specific recommendations for right-sizing instances based on utilization. Option C (incorrect) primarily provides recommendations for EC2 instances, not directly for SageMaker training jobs, which manage their own underlying infrastructure. While SageMaker training jobs run on EC2 instances, the direct SageMaker-specific metrics are more relevant. Option D (incorrect) is designed for optimizing inference endpoints, not training jobs.', 17, 'm_17_2', 3, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data science team is training a large deep learning model on Amazon SageMaker. The training jobs are fault-tolerant and can tolerate interruptions, but they are very compute-intensive and run for several hours. The team needs to reduce training costs significantly. Which SageMaker feature should they leverage to achieve the MOST cost savings for these specific training jobs?', '["Utilize Amazon SageMaker Managed Spot Training to bid on unused EC2 capacity.","Implement SageMaker warm pools to keep instances ready for immediate use.","Schedule training jobs during off-peak hours to take advantage of lower demand.","Use SageMaker Distributed Training libraries to parallelize the workload across more instances."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective way to achieve significant cost savings for fault-tolerant, compute-intensive training jobs. Amazon SageMaker Managed Spot Training allows users to specify a maximum price for instances or let SageMaker manage the bidding, leveraging unused EC2 Spot Instance capacity, which can be significantly cheaper than On-Demand instances. Option B (incorrect) is for reducing startup times for frequently used instances, not primarily for cost savings. Option C (incorrect) might offer some minor cost benefits if pricing tiers vary by time, but it''s not a direct cost-saving mechanism like Spot Instances. Option D (incorrect) is for accelerating training by distributing the workload, which might increase overall compute usage and thus cost, even if it reduces wall-clock time.', 17, 'm_17_2', 4, NULL, NULL),
  ('mock_14_all_1774921932068', 'A financial institution has deployed a critical credit risk model on an Amazon SageMaker endpoint. They need to be immediately notified if the model starts returning an unusually high number of prediction errors, indicating a potential issue with the model or underlying data. This notification should trigger an automated response. Which combination of services should be used to achieve this with LEAST operational overhead?', '["Configure Amazon CloudWatch Alarms on the `InvocationErrors` metric for the SageMaker endpoint and link it to an Amazon SNS topic.","Manually review Amazon CloudWatch Logs for the SageMaker endpoint every hour to detect error patterns.","Implement a custom AWS Lambda function to periodically invoke the endpoint and check for errors, then send an email.","Use Amazon SageMaker Model Monitor to detect data quality issues and configure it to send alerts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most efficient and automated solution with the least operational overhead. Amazon CloudWatch automatically collects `InvocationErrors` metrics for SageMaker endpoints. Configuring a CloudWatch Alarm on this metric to trigger an Amazon SNS topic for notifications is a standard, fully managed, and highly effective approach. Option B (incorrect) involves manual review, which is high operational overhead, prone to delays, and not suitable for immediate notification. Option C (incorrect) requires developing, deploying, and maintaining a custom Lambda function, increasing operational overhead compared to using native CloudWatch Alarms. Option D (incorrect) is designed for detecting data and model quality drift, not for immediate alerts on `InvocationErrors` which are infrastructure-level operational metrics.', 17, 'm_17_2', 5, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data science manager wants to track and understand the monthly spending on Amazon SageMaker training jobs across different projects and teams. They need to visualize costs, identify cost trends, and attribute costs to specific business units. Which AWS service is purpose-built for this financial management task?', '["AWS Budgets to set spending limits and receive alerts when thresholds are exceeded.","AWS Organizations to consolidate billing for multiple AWS accounts.","AWS Cost Explorer to visualize, understand, and manage AWS costs over time, including SageMaker.","Amazon CloudWatch to monitor resource utilization metrics and infer cost implications."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the primary service for visualizing, understanding, and managing AWS costs, including those from Amazon SageMaker. AWS Cost Explorer allows users to analyze historical spending, identify trends, forecast future costs, and filter costs by service, tags, or accounts, making it ideal for attributing costs to specific projects or teams. Option A (incorrect) is for setting spending alerts, not for detailed cost analysis and visualization. Option B (incorrect) is for managing multiple AWS accounts under a single billing entity, not for detailed cost analysis within an account. Option D (incorrect) monitors resource utilization, which can indirectly help with cost optimization, but it does not directly provide cost visualization or attribution capabilities.', 17, 'm_17_2', 6, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company has deployed a machine learning model on an Amazon SageMaker real-time inference endpoint. The model experiences predictable spikes in traffic during specific hours of the day, requiring more instances to maintain low latency. The team wants to ensure the endpoint scales automatically to meet demand while optimizing costs. Which approach is MOST suitable?', '["Manually adjust the number of instances for the SageMaker endpoint before and after peak hours.","Configure SageMaker endpoint auto-scaling based on a target metric like `InvocationsPerInstance`.","Deploy the model on a large, single instance type that can handle maximum peak load 24/7.","Use Amazon SageMaker Batch Transform to process all inference requests once daily."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable approach for automatically scaling an Amazon SageMaker real-time inference endpoint to handle predictable traffic spikes while optimizing costs. SageMaker endpoint auto-scaling dynamically adjusts the number of instances based on configured target metrics (like `InvocationsPerInstance` or `TargetUtilization`), ensuring that resources are provisioned only when needed. Option A (incorrect) introduces significant operational overhead and is prone to human error, potentially leading to performance issues or unnecessary costs. Option C (incorrect) would lead to substantial over-provisioning and high costs during off-peak hours. Option D (incorrect) is for batch inference, not for real-time inference that requires immediate responses to individual requests.', 17, 'm_17_2', 7, NULL, NULL);

