-- Module: m_17_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774921932068', 'A healthcare provider uses an Amazon SageMaker endpoint for real-time diagnosis predictions. Over time, the distribution of incoming patient data has subtly shifted, causing the model''s accuracy to degrade without any changes to the model itself. The MLOps team needs to automatically detect these shifts in input data distribution. Which SageMaker feature should they implement?', '["Configure Amazon CloudWatch Alarms on the SageMaker endpoint''s `InvocationErrors` metric.","Implement Amazon SageMaker Model Monitor to detect data quality drift.","Regularly retrain the model on a fixed schedule, regardless of data changes.","Use AWS CloudTrail to track API calls related to data input to the endpoint."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for this use case. Amazon SageMaker Model Monitor can be configured to continuously monitor the data ingested by a SageMaker endpoint and compare its statistical properties against a baseline, effectively detecting data quality drift (which includes shifts in input data distribution). Option A (incorrect) monitors infrastructure errors, not data distribution changes or model accuracy degradation. Option C (incorrect) is an anti-pattern ([ap-4.2-001]) because it doesn''t react to actual drift, potentially missing rapid shifts or retraining unnecessarily. Option D (incorrect) tracks API calls for auditing purposes, not for analyzing data distribution.', 17, 'm_17_1', 8, NULL, NULL),
  ('mock_14_all_1774921932068', 'A retail company uses an Amazon SageMaker endpoint for personalized product recommendations. They observe that the recommendations have become less relevant over the past few weeks, indicating a potential degradation in model performance. The team wants to proactively detect when the model''s predictive quality falls below an acceptable threshold. Which SageMaker feature should they use?', '["Set up Amazon CloudWatch metrics to monitor the endpoint''s CPU and memory utilization.","Implement Amazon SageMaker Model Monitor to detect model quality drift.","Manually review a sample of recommendations daily and compare them to ground truth.","Use Amazon SageMaker ML Lineage Tracking to trace the origin of the input data."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective solution for detecting model quality degradation. Amazon SageMaker Model Monitor can be configured to continuously evaluate the predictions from an endpoint against ground truth labels (when available) and detect model quality drift, such as a decrease in accuracy, precision, or recall. Option A (incorrect) monitors infrastructure health, not the quality of the model''s predictions ([ap-4.1-001]). Option C (incorrect) is a manual, high-overhead process that is not scalable or proactive. Option D (incorrect) is for tracking the lineage of ML artifacts, not for monitoring the real-time performance quality of a deployed model.', 17, 'm_17_1', 9, NULL, NULL),
  ('mock_14_all_1774921932068', 'A financial services company has deployed a credit scoring model on Amazon SageMaker. They need an automated system to alert them immediately if the model''s performance (e.g., accuracy) degrades significantly due to data drift. This alert should trigger a notification to the MLOps team. Which combination of services provides this capability with automated alerts?', '["Configure Amazon SageMaker Model Monitor for model quality drift and integrate it with Amazon CloudWatch Alarms.","Set up Amazon CloudWatch Alarms on the SageMaker endpoint''s `ModelLatency` metric.","Use AWS CloudTrail to log model invocation events and filter for errors.","Implement a scheduled AWS Lambda function to periodically evaluate model performance and send emails."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the required automated alerts for model performance degradation due to drift. Amazon SageMaker Model Monitor can detect model quality drift, and it integrates seamlessly with Amazon CloudWatch Alarms. When a drift is detected, Model Monitor can publish metrics to CloudWatch, which can then trigger an alarm and send notifications (e.g., via Amazon SNS) to the MLOps team. Option B (incorrect) monitors inference latency, not model quality or drift. Option C (incorrect) is for auditing API calls, not for monitoring model performance or detecting drift. Option D (incorrect) involves developing and maintaining custom code, increasing operational overhead compared to the native integration of SageMaker Model Monitor and CloudWatch Alarms.', 17, 'm_17_1', 10, NULL, NULL),
  ('mock_14_all_1774921932068', 'An e-commerce company uses an Amazon SageMaker endpoint for product recommendation. They recently discovered that the model''s recommendations show an unintended bias towards certain demographics, which is causing customer dissatisfaction. The MLOps team needs to continuously monitor the model in production to detect and alert on such bias drift. Which SageMaker feature is designed for this specific purpose?', '["Amazon CloudWatch Logs for the SageMaker endpoint to analyze inference requests.","Amazon SageMaker Model Monitor with bias drift monitoring.","AWS CloudTrail to audit SageMaker API calls for potential configuration changes.","Amazon SageMaker ML Lineage Tracking to understand the data sources."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the specific feature designed to address this problem. Amazon SageMaker Model Monitor includes capabilities for detecting bias drift in production models. It can monitor for shifts in bias metrics over time, alerting the team if the model''s predictions start exhibiting unintended biases. Option A (incorrect) provides raw logs which would require significant custom effort to analyze for bias. Option C (incorrect) is for auditing API calls, not for monitoring model bias. Option D (incorrect) tracks the lineage of ML artifacts, which can help in understanding the data''s origin but does not actively monitor for bias drift in deployed models.', 17, 'm_17_1', 11, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data science team manages a critical forecasting model deployed on Amazon SageMaker. They have observed that the model''s accuracy degrades significantly when the underlying data distribution changes, requiring retraining. The team wants to implement a strategy that automatically triggers model retraining only when data drift is detected, in addition to a regular scheduled retraining. Which approach BEST achieves this?', '["Implement Amazon SageMaker Model Monitor to detect data drift, which then triggers an AWS Lambda function to start a new SageMaker training job.","Schedule SageMaker training jobs to run weekly, regardless of any data drift detection.","Manually monitor data distributions in Amazon S3 and trigger retraining when significant changes are observed.","Set up Amazon CloudWatch Alarms on SageMaker endpoint `CPUUtilization` to trigger retraining when high."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best approach for implementing drift-triggered retraining. Amazon SageMaker Model Monitor can detect data drift, and when a drift is detected, it can publish metrics to Amazon CloudWatch. A CloudWatch Alarm can then be configured to trigger an AWS Lambda function, which in turn can initiate a new SageMaker training job. This combines drift detection with automated retraining, addressing the anti-pattern ([ap-4.2-001]) of only retraining on a fixed schedule. Option B (incorrect) is an anti-pattern ([ap-4.2-001]) as it does not react to unpredictable data shifts, potentially leading to prolonged periods of degraded model performance. Option C (incorrect) is a manual process, which is not scalable, introduces operational overhead, and is prone to delays. Option D (incorrect) monitors infrastructure utilization, not data drift, and high CPU utilization does not directly indicate a need for model retraining.', 17, 'm_17_1', 12, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company uses a complex deep learning model for image classification on Amazon SageMaker. They have noticed that the model''s explanations (feature attributions) are becoming less consistent with human intuition over time, even if the overall accuracy remains acceptable. The MLOps team needs to detect these shifts in feature importance. Which SageMaker Model Monitor capability should they utilize?', '["Model quality drift monitoring to track overall performance metrics like accuracy.","Data quality drift monitoring to detect changes in input data distributions.","Bias drift monitoring to identify shifts in model fairness metrics.","Feature attribution drift monitoring to detect changes in feature importance."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the specific capability within Amazon SageMaker Model Monitor designed for this scenario. Feature attribution drift monitoring detects when the importance or contribution of features to a model''s prediction changes over time, which can indicate issues even if overall model quality metrics like accuracy remain stable. Option A (incorrect) focuses on overall model performance metrics, not the interpretability aspect. Option B (incorrect) detects changes in the input data itself, not how the model uses those features. Option C (incorrect) focuses on fairness metrics, which is a different aspect of model behavior.', 17, 'm_17_1', 13, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data science team has deployed an Amazon SageMaker endpoint for real-time inference. They want to ensure that if the model''s accuracy drops below a predefined threshold, an automatic retraining process is initiated. This process should be triggered by the detection of model performance degradation. Which combination of SageMaker and CloudWatch services should be used?', '["Use Amazon CloudWatch to monitor endpoint `Invocations` and trigger an AWS Lambda function for retraining.","Configure Amazon SageMaker Model Monitor for model quality drift, publishing metrics to CloudWatch, and set up a CloudWatch Alarm to trigger retraining.","Manually review model predictions periodically and trigger retraining if accuracy appears low.","Implement Amazon SageMaker ML Lineage Tracking to identify the source of poor-performing models."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the most automated and integrated solution for drift-triggered retraining. Amazon SageMaker Model Monitor can continuously assess the model''s quality in production. If it detects model quality drift (e.g., accuracy degradation), it publishes corresponding metrics to Amazon CloudWatch. A CloudWatch Alarm can then be configured on these metrics to trigger an automated action, such as invoking an AWS Lambda function that starts a new SageMaker training job. Option A (incorrect) monitors invocation counts, not model accuracy, and is not suitable for drift detection. Option C (incorrect) is a manual, high-overhead process that lacks automation and real-time response. Option D (incorrect) is for tracking the provenance of ML artifacts, not for triggering retraining based on performance degradation.', 17, 'm_17_1', 14, NULL, NULL);

