INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774921932068', 'A pharmaceutical company is training a new drug discovery model using Amazon SageMaker. Due to strict regulatory requirements, all training jobs must run in a private network environment with no direct public internet access to prevent data exfiltration and ensure security. Which networking configuration should be applied to the SageMaker training job?', '["Configure the SageMaker training job to run in a Virtual Private Cloud (VPC) with no public internet access and use VPC endpoints for AWS service access.","Allow the SageMaker training job to use public internet access but implement strict security group rules to limit outbound traffic.","Run the SageMaker training job outside of a VPC and rely solely on IAM policies for data security.","Use AWS Secrets Manager to store sensitive data, which inherently prevents public internet access during training."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the recommended and most secure approach for running SageMaker training jobs in regulated environments. Configuring the training job to run within a Virtual Private Cloud (VPC) with no public internet access, and using VPC endpoints for secure and private communication with other AWS services (like Amazon S3 for data) ensures network isolation and prevents data exfiltration, directly addressing the anti-pattern ([ap-4.3-001]). Option B (incorrect) is an anti-pattern ([ap-4.3-001]) as it still allows direct internet access, which is a security risk in regulated environments. Security group rules alone might not be sufficient to prevent all forms of data exfiltration or downloading malicious packages. Option C (incorrect) offers no network isolation and is highly insecure for sensitive data. Option D (incorrect) is for managing credentials, not for providing network isolation for training jobs.', 17, 'm_17_3', 15, NULL, NULL),
  ('mock_14_all_1774921932068', 'A data scientist needs to grant an Amazon SageMaker training job permission to read data from a specific Amazon S3 bucket and write model artifacts back to another S3 bucket. The principle of least privilege must be strictly followed. Which AWS service is primarily used to define these permissions for the SageMaker training job?', '["AWS KMS to encrypt the S3 buckets, implicitly controlling access.","AWS IAM to create an execution role with specific S3 read/write policies.","Amazon VPC to define network access rules for the training job.","AWS Secrets Manager to store credentials for S3 access."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the primary service for defining permissions in AWS. AWS IAM (Identity and Access Management) allows the creation of an execution role for the SageMaker training job. This role can then be assigned specific IAM policies that grant only the necessary permissions, such as `s3:GetObject` for the input bucket and `s3:PutObject` for the output bucket, adhering to the principle of least privilege. Option A (incorrect) is for encryption, not for defining access permissions. While encryption can protect data, it doesn''t grant or deny access to the resource itself. Option C (incorrect) defines network access, not resource-level permissions. Option D (incorrect) is for securely storing credentials, but the permissions themselves are defined by IAM.', 17, 'm_17_3', 16, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company is storing sensitive customer data in an Amazon S3 bucket, which is used as input for Amazon SageMaker training jobs. To meet compliance requirements, all data at rest must be encrypted with customer-managed keys. Which encryption method should be configured for the S3 bucket to meet this requirement with AWS Key Management Service (AWS KMS)?', '["Server-Side Encryption with Amazon S3-Managed Keys (SSE-S3).","Server-Side Encryption with AWS KMS Keys (SSE-KMS) using a customer-managed key (CMK).","Client-Side Encryption where the application encrypts data before uploading to S3.","Server-Side Encryption with Customer-Provided Keys (SSE-C)."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate method for encrypting data at rest in Amazon S3 with customer-managed keys using AWS KMS. SSE-KMS allows you to use a customer-managed key (CMK) that you create and control within AWS KMS, fulfilling the requirement for customer-managed keys. Option A (incorrect) uses AWS-managed keys, not customer-managed keys. Option C (incorrect) places the burden of encryption and key management on the application, increasing operational complexity and potentially not meeting the ''AWS KMS'' aspect of the requirement. Option D (incorrect) requires the customer to manage and provide their own encryption keys, which is different from using a customer-managed key within AWS KMS.', 17, 'm_17_3', 17, NULL, NULL),
  ('mock_14_all_1774921932068', 'A machine learning pipeline on Amazon SageMaker needs to access a third-party API for feature enrichment during training. The API requires an authentication token that is highly sensitive and must be securely stored and managed. Which AWS service is the MOST appropriate for storing and retrieving this API token within the SageMaker environment?', '["Store the token directly in environment variables of the SageMaker training job.","Embed the token directly in the training script stored in Amazon S3.","Use AWS Secrets Manager to store the token and retrieve it at runtime.","Encrypt the token and store it in an Amazon S3 bucket with restricted access."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most secure and recommended way to store and manage sensitive credentials like API tokens. AWS Secrets Manager is purpose-built for securely storing, managing, and retrieving secrets throughout their lifecycle. It integrates well with SageMaker, allowing the training job to retrieve the secret at runtime without hardcoding it. Option A (incorrect) is less secure as environment variables can be more easily exposed or logged. Option B (incorrect) is highly insecure as it hardcodes the secret directly into the code, making it vulnerable to exposure. Option D (incorrect) is better than hardcoding, but Secrets Manager provides more robust secret rotation, auditing, and access control features specifically designed for credentials.', 17, 'm_17_3', 18, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company is deploying an Amazon SageMaker real-time inference endpoint that processes highly sensitive personal identifiable information (PII). To comply with data privacy regulations, the endpoint must not be accessible from the public internet and all network traffic to and from the endpoint must be isolated within a private network. Which AWS service configuration is required to achieve this network isolation?', '["Configure the SageMaker endpoint to use a public subnet and apply strict security group rules.","Deploy the SageMaker endpoint within an Amazon Virtual Private Cloud (VPC) with private subnets and no public IP addresses.","Use AWS WAF to filter incoming traffic to the SageMaker endpoint.","Rely on IAM policies to restrict access to the SageMaker endpoint, without specific network configurations."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the correct approach for achieving network isolation for a SageMaker inference endpoint. Deploying the endpoint within an Amazon VPC, specifically in private subnets without public IP addresses, ensures that the endpoint is not accessible from the public internet and all traffic remains within the private network. Option A (incorrect) still exposes the endpoint to the public internet, even with security group rules, which violates the ''no public internet access'' requirement. Option C (incorrect) is a web application firewall that protects against common web exploits, but it does not provide fundamental network isolation from the public internet for a SageMaker endpoint. Option D (incorrect) controls who can access the endpoint, but it does not provide network isolation, meaning the endpoint could still be publicly accessible if not configured within a VPC.', 17, 'm_17_3', 19, NULL, NULL),
  ('mock_14_all_1774921932068', 'A large enterprise is setting up an Amazon SageMaker Studio environment for multiple data science teams. Each team needs its own isolated workspace, and administrators must be able to control which AWS resources (e.g., specific S3 buckets, SageMaker notebook instances) each user or team can access. Which AWS service is fundamental for implementing these granular access controls and multi-user isolation within SageMaker Studio?', '["AWS CloudTrail to log all user activities within SageMaker Studio.","AWS Secrets Manager to store credentials for each user''s access.","AWS IAM to define user profiles, execution roles, and resource-based policies for SageMaker Studio.","Amazon VPC to create separate network environments for each data science team."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the fundamental service for implementing granular access controls and multi-user isolation within Amazon SageMaker Studio. AWS IAM allows administrators to create IAM users and roles, define execution roles for SageMaker Studio users, and attach policies that specify exactly which AWS resources (like S3 buckets, SageMaker notebook instances, or specific SageMaker APIs) each user or team can access, adhering to the principle of least privilege. Option A (incorrect) is for auditing and logging API calls, not for defining access permissions. Option B (incorrect) is for securely storing credentials, not for defining user access policies. Option D (incorrect) provides network isolation but does not define granular resource-level access controls for individual users or teams within SageMaker Studio.', 17, 'm_17_3', 20, NULL, NULL),
  ('mock_14_all_1774921932068', 'A company is building a real-time inference pipeline using Amazon SageMaker endpoints. The data being transmitted between client applications and the SageMaker endpoint, and between the endpoint and other AWS services (like Amazon S3 for model artifacts), contains sensitive information. To meet security and compliance requirements, all data in transit must be encrypted. Which approach ensures encryption of data in transit for this pipeline?', '["Configure Server-Side Encryption with AWS KMS for all Amazon S3 buckets used by SageMaker.","Ensure all communication with SageMaker endpoints and other AWS services uses TLS/SSL.","Implement client-side encryption for data before sending it to the SageMaker endpoint.","Use Amazon VPC to isolate the SageMaker endpoint, which implicitly encrypts all traffic."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the standard and most effective approach to ensure encryption of data in transit. AWS services, including Amazon SageMaker, automatically enforce TLS/SSL (Transport Layer Security/Secure Sockets Layer) for all API calls and data transfers between services and clients. This encrypts data as it travels over the network. Option A (incorrect) ensures encryption of data at rest in S3, not data in transit. Option C (incorrect) would encrypt the payload, but the transport layer itself still relies on TLS/SSL for secure communication channels. While client-side encryption adds another layer of security, TLS/SSL is the primary mechanism for data in transit. Option D (incorrect) provides network isolation, but it does not inherently encrypt data in transit; TLS/SSL is still required for encryption over the network, even within a VPC.', 17, 'm_17_3', 21, NULL, NULL);

