INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774923300597', 'A data science team is preparing a new dataset for a fraud detection model. They suspect the dataset might contain inherent biases related to certain demographic attributes, which could lead to unfair model predictions. The team needs to proactively identify and quantify these biases before training the model, with the goal of ensuring fairness and transparency. Which AWS service should the team use to detect and measure potential biases in their training dataset?', '["Amazon SageMaker Clarify","Amazon SageMaker Ground Truth","AWS Glue DataBrew","Amazon SageMaker Feature Store"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker Clarify, which is specifically designed to help detect potential bias in ML models and data. It can analyze datasets for bias before training and explain model predictions, ensuring fairness and transparency. Option B (incorrect) is Amazon SageMaker Ground Truth, which is used for building high-quality training datasets by labeling data, not for bias detection. Option C (incorrect) is AWS Glue DataBrew, a visual data preparation tool for cleaning and normalizing data, but it does not specialize in bias detection. Option D (incorrect) is Amazon SageMaker Feature Store, which is used for storing, sharing, and managing curated features for ML models, not for analyzing bias in raw datasets.', 14, 'm_14_3', 1, NULL, NULL),
  ('mock_14_all_1774923300597', 'A financial institution is building a machine learning model to predict stock prices based on historical time-series data. The data scientists are preparing the dataset for training and evaluation. To ensure the model''s performance is realistically assessed and to prevent data leakage, they need to split the dataset into training, validation, and test sets. Which data splitting strategy is the MOST appropriate for this time-series dataset?', '["Random split, ensuring an even distribution across all sets.","Time-based split, where training data chronologically precedes validation and test data.","Stratified split, maintaining the proportion of target classes across all sets.","K-fold cross-validation, randomly partitioning the data into K subsets."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the time-based split. For time-series data, it is crucial that the training data chronologically precedes the validation and test data. This simulates a real-world scenario where the model predicts future events based on past data, preventing data leakage from the future into the training set. Option A (incorrect) is a random split, which is an anti-pattern for time-series data ([ap-1.3-001]) as it can cause future data to leak into the training set, leading to an unrealistically optimistic model evaluation. Option C (incorrect) is a stratified split, which is useful for maintaining class distribution in classification problems but is not the primary concern for time-series data. Option D (incorrect) is K-fold cross-validation, which also typically involves random partitioning and is not suitable for time-series data due to the temporal dependencies.', 14, 'm_14_3', 2, NULL, NULL),
  ('mock_14_all_1774923300597', 'A healthcare provider is preparing a large patient dataset for a new diagnostic ML model. The dataset contains various types of medical records, and ensuring data quality (completeness, consistency, accuracy, uniqueness) is critical before training. The data engineering team needs a serverless solution to perform these data quality checks and generate reports with LEAST operational overhead. Which AWS service combination best meets this requirement?', '["Amazon SageMaker Processing with custom Python scripts for data quality checks.","AWS Glue with custom PySpark scripts for data quality checks.","AWS Glue DataBrew for visual data profiling and quality checks.","Amazon Athena queries directly on Amazon S3 data for quality checks."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Glue DataBrew. DataBrew is a visual data preparation tool that allows users to clean, normalize, and perform data quality checks without writing code. It provides built-in data profiling capabilities to identify completeness, consistency, and uniqueness issues, making it ideal for ensuring data integrity with the least operational overhead. Option A (incorrect) involves Amazon SageMaker Processing, which can run custom scripts but requires more operational effort to develop and maintain the scripts compared to DataBrew''s visual interface. Option B (incorrect) uses AWS Glue with custom PySpark scripts, which is powerful for ETL but also requires significant coding and operational management for script development and maintenance. Option D (incorrect) uses Amazon Athena, which is great for querying data lakes, but performing comprehensive data quality checks and generating detailed reports would require complex SQL queries and additional tooling, increasing operational overhead.', 14, 'm_14_3', 3, NULL, NULL),
  ('mock_14_all_1774923300597', 'A startup is developing an image recognition model for identifying specific objects in satellite imagery. They have collected millions of raw satellite images stored in Amazon S3, but these images lack labels indicating the presence and location of the target objects. The team needs an efficient and scalable way to label these images for supervised machine learning training. Which AWS service is best suited for this task?', '["Amazon SageMaker Processing","AWS Glue DataBrew","Amazon SageMaker Clarify","Amazon SageMaker Ground Truth"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon SageMaker Ground Truth. It is a fully managed data labeling service that makes it easy to build highly accurate training datasets for machine learning. It supports various data types, including images, and allows for human annotators (either internal or through Amazon Mechanical Turk) to label data efficiently. Option A (incorrect) is Amazon SageMaker Processing, which is used for running data processing jobs, not for interactive human labeling. Option B (incorrect) is AWS Glue DataBrew, a visual data preparation tool, but it does not provide human labeling capabilities. Option C (incorrect) is Amazon SageMaker Clarify, used for detecting bias and explaining model predictions, not for creating labeled datasets.', 14, 'm_14_3', 4, NULL, NULL),
  ('mock_14_all_1774923300597', 'A data science team is working on a critical ML project that involves multiple data transformations and feature engineering steps. For auditing, debugging, and reproducibility, they need to track the lineage of their data, including how datasets are created, transformed, and used in different model training jobs. Which AWS service or feature provides the MOST effective way to establish and track this data and model lineage?', '["Amazon SageMaker ML Lineage Tracking","AWS Glue Data Catalog","Amazon S3 Versioning","AWS Lake Formation"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker ML Lineage Tracking. This feature specifically allows data scientists and developers to track the lineage of ML artifacts (data, models, code, and parameters) across the entire ML workflow. It provides a comprehensive view of how datasets are transformed and used, crucial for auditability and reproducibility. Option B (incorrect) is AWS Glue Data Catalog, which stores metadata about data in a data lake but does not track the operational lineage of transformations and model training jobs. Option C (incorrect) is Amazon S3 Versioning, which keeps multiple versions of an object in an S3 bucket, useful for data recovery but not for tracking ML workflow lineage. Option D (incorrect) is AWS Lake Formation, which helps build secure data lakes but does not provide detailed ML lineage tracking capabilities.', 14, 'm_14_3', 5, NULL, NULL),
  ('mock_14_all_1774923300597', 'A retail company is developing a customer churn prediction model. The dataset includes customer demographics, purchase history, and interaction data. The data science team is concerned about potential bias in the training data, specifically regarding how certain sensitive attributes (e.g., age group, region) might correlate with churn outcomes, leading to an unfair model. They need to analyze the dataset to identify these correlations and measure the extent of bias. Which AWS service should they use?', '["Amazon SageMaker Ground Truth to label sensitive attributes.","Amazon SageMaker Clarify to detect and measure bias in the dataset.","AWS Glue DataBrew to clean and normalize the data.","Amazon SageMaker Feature Store to manage the features."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon SageMaker Clarify. SageMaker Clarify is designed to detect and measure bias in ML datasets and models, both before training (pre-training bias) and after training (post-training bias). It can analyze correlations between sensitive attributes and target variables, helping to identify fairness issues. This directly addresses the anti-pattern of not detecting and measuring bias in training datasets ([ap-1.3-002]). Option A (incorrect) is Amazon SageMaker Ground Truth, which is used for data labeling, not for bias detection. Option C (incorrect) is AWS Glue DataBrew, a visual data preparation tool for cleaning and transforming data, but it does not specialize in bias analysis. Option D (incorrect) is Amazon SageMaker Feature Store, used for storing and managing features, not for bias detection.', 14, 'm_14_3', 6, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_14_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774923300597', 'A media company collects petabytes of user interaction data, content metadata, and viewing habits. This data is stored in an Amazon S3-based data lake. Data scientists frequently run ad-hoc analytical queries on this data for feature engineering and exploratory data analysis using Amazon Athena. The company wants to optimize query performance and reduce costs for these analytical workloads. Which data format should they primarily use for storing their ML data in Amazon S3?', '["CSV (Comma Separated Values), as it is human-readable and widely supported.","JSON (JavaScript Object Notation), for its flexibility with semi-structured data.","TFRecord, a binary format optimized for TensorFlow.","Parquet, a columnar storage format optimized for analytical queries."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Parquet. Parquet is a columnar storage format that provides significant advantages for analytical workloads in data lakes, especially when queried by services like Amazon Athena. It offers high compression ratios and predicate pushdown, meaning Athena can read only the necessary columns and rows, drastically reducing query costs and improving performance. Option A (incorrect) is CSV, which is a row-based format and an anti-pattern for analytical ML workloads ([ap-1.1-002]) because it is less efficient for querying specific columns and offers poorer compression. Option B (incorrect) is JSON, also a row-based format, which is flexible but less performant and more costly for large-scale analytical queries compared to columnar formats. Option C (incorrect) is TFRecord, a binary format optimized for TensorFlow, but not universally optimal for general analytical queries in a data lake context.', 14, 'm_14_1', 7, NULL, NULL),
  ('mock_14_all_1774923300597', 'A manufacturing company needs to ingest real-time sensor data from factory equipment for predictive maintenance models. The data arrives continuously in high volume and needs to be processed and stored for near real-time analysis and future machine learning training. The solution must be scalable, fully managed, and support streaming data ingestion. Which AWS service is best suited for ingesting this real-time data stream?', '["Amazon Kinesis Data Streams","AWS Glue","Amazon S3","Amazon Redshift"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon Kinesis Data Streams. Kinesis Data Streams is a highly scalable and fully managed service designed for real-time processing of large streams of data records. It allows for continuous data ingestion from sources like sensor data, making it ideal for the described scenario. Option B (incorrect) is AWS Glue, which is primarily an ETL service for batch processing and data cataloging, not optimized for real-time streaming ingestion. Option C (incorrect) is Amazon S3, an object storage service, suitable for storing large volumes of data but not for direct real-time streaming ingestion and processing. Option D (incorrect) is Amazon Redshift, a data warehouse service, suitable for analytical queries on structured data, but not for direct real-time ingestion of raw streams.', 14, 'm_14_1', 8, NULL, NULL),
  ('mock_14_all_1774923300597', 'A research institution receives daily batches of scientific measurement data, typically in CSV format, which are uploaded to an Amazon S3 bucket. This data needs to be cataloged and made easily queryable for various machine learning experiments and feature engineering tasks. The institution requires a serverless solution that can automatically discover the schema of these files and register them, enabling SQL-based queries. Which AWS service combination fulfills this requirement with LEAST operational overhead?', '["Manually create tables in Amazon Athena for each new dataset.","Use AWS Glue Crawlers to discover schema and populate the AWS Glue Data Catalog, then query with Amazon Athena.","Load data into Amazon Redshift and query it directly.","Use Amazon Kinesis Data Firehose to ingest data into Amazon S3 and then query with Amazon Redshift Spectrum."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is to use AWS Glue Crawlers to discover schema and populate the AWS Glue Data Catalog, then query with Amazon Athena. AWS Glue Crawlers automatically infer schemas from data stored in S3 and register them in the AWS Glue Data Catalog. Amazon Athena can then use this catalog to run SQL queries directly on the data in S3, providing a serverless and low-overhead solution for making batch data queryable for ML. Option A (incorrect) involves manually creating tables in Amazon Athena, which is high operational overhead and prone to errors for daily batch updates. Option C (incorrect) suggests loading data into Amazon Redshift, which is a data warehouse and incurs higher operational overhead and cost compared to a serverless data lake approach for ad-hoc queries. Option D (incorrect) uses Amazon Kinesis Data Firehose, which is for streaming data, not batch, and Redshift Spectrum would still require a catalog, adding complexity.', 14, 'm_14_1', 9, NULL, NULL),
  ('mock_14_all_1774923300597', 'A data science team is building a fraud detection model and has collected a massive dataset of transactional records. This data is stored in Amazon S3 and will be used for training and analytical queries. To optimize the performance and cost of querying this data using Amazon Athena and Amazon Redshift Spectrum, the team wants to convert the raw CSV files into a more efficient format. Which data format should they choose to achieve the BEST query performance and cost efficiency?', '["JSON, due to its human-readable nature and flexibility.","CSV, as it is a common and simple text-based format.","ORC (Optimized Row Columnar), for its columnar storage and compression benefits.","RecordIO, a binary format optimized for SageMaker algorithms."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is ORC (Optimized Row Columnar). ORC is a columnar storage format, similar to Parquet, that is highly optimized for analytical queries. It provides excellent compression and allows query engines like Amazon Athena and Amazon Redshift Spectrum to read only the necessary columns and rows, significantly reducing I/O operations, improving query performance, and lowering costs. This directly addresses the anti-pattern of storing all ML data in row-based formats ([ap-1.1-002]). Option A (incorrect) is JSON, a row-based format that is less efficient for analytical queries due to higher I/O and lack of columnar optimization. Option B (incorrect) is CSV, also a row-based format and an anti-pattern for large-scale analytical workloads due to poor compression and query performance. Option D (incorrect) is RecordIO, a binary format primarily optimized for specific SageMaker algorithms, not a general-purpose format for cost-effective analytical querying in a data lake.', 14, 'm_14_1', 10, NULL, NULL),
  ('mock_14_all_1774923300597', 'A machine learning engineer is training a large language model on a massive dataset (hundreds of gigabytes) stored in Amazon S3. The training job is running on Amazon SageMaker. To maximize the efficiency of the training process and avoid bottlenecks caused by data loading, the engineer wants to ensure that the data is streamed directly to the training instances as needed, rather than being fully downloaded upfront. Which SageMaker data input mode should be used to achieve this goal?', '["File mode, which downloads the entire dataset before training.","FastFile mode, which uses an optimized file system for faster downloads.","Augmented Manifest File mode, for handling incrementally labeled data.","Pipe mode, which streams data directly from Amazon S3 to the training container."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Pipe mode. Pipe mode is designed for streaming data directly from Amazon S3 to the SageMaker training container. This approach avoids the need to download the entire dataset to the training instance''s local storage before training begins, significantly reducing startup times and improving efficiency for large datasets. Option A (incorrect) is File mode, which is an anti-pattern for large-scale SageMaker training jobs ([ap-1.1-001]) as it downloads the entire dataset, causing significant startup latency. Option B (incorrect) is FastFile mode, which is an optimized version of File mode for specific file systems, but still involves downloading the data rather than streaming it directly. Option C (incorrect) is Augmented Manifest File mode, which is used for incremental training with data labeled by SageMaker Ground Truth, not primarily for optimizing large dataset streaming.', 14, 'm_14_1', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_14_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774923300597', 'A data science team has developed a new fraud detection model. They have performed extensive feature engineering during training, including normalization and encoding categorical variables. Now, they are deploying the model to production for real-time inference. It is critical to ensure that the feature transformations applied during inference are IDENTICAL to those applied during training to prevent training-serving skew. Which AWS service or approach helps maintain this consistency with LEAST operational overhead?', '["Amazon SageMaker Feature Store to store and serve consistent features for both training and inference.","Manually replicate transformation logic in the inference code.","Use AWS Glue DataBrew for feature engineering during training and then manually export the transformation recipe for inference.","Store pre-computed features in Amazon S3 for both training and inference."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker Feature Store. SageMaker Feature Store is designed to store, share, and manage curated features for machine learning. It ensures that the same feature engineering logic and computed feature values are used consistently across both training and inference, directly addressing the anti-pattern of training-serving skew ([ap-1.2-002]) with minimal operational overhead. Option B (incorrect) involves manually replicating transformation logic in inference code, which is prone to errors and high operational overhead, increasing the risk of training-serving skew. Option C (incorrect) uses AWS Glue DataBrew for training, but manually exporting and integrating the recipe into inference code still introduces manual steps and potential inconsistencies. Option D (incorrect) suggests storing pre-computed features in Amazon S3, which is a storage solution but doesn''t inherently ensure consistent feature computation logic between training and inference.', 14, 'm_14_2', 12, NULL, NULL),
  ('mock_14_all_1774923300597', 'A retail company has terabytes of raw customer transaction data stored in Amazon S3. A data engineering team needs to perform complex ETL (Extract, Transform, Load) operations, including data cleaning, aggregation, and feature engineering, to prepare this data for machine learning model training. The team requires a serverless, scalable, and cost-effective solution that can handle large datasets efficiently. Which AWS service is best suited for this batch ETL workload?', '["Amazon SageMaker Data Wrangler","AWS Glue","Amazon SageMaker Processing","Amazon Athena"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Glue. AWS Glue is a fully managed, serverless ETL service that makes it easy to prepare and load data for analytics and machine learning. It supports large-scale data processing using Apache Spark, making it ideal for transforming terabytes of raw data into features efficiently and cost-effectively without managing servers. Option A (incorrect) is Amazon SageMaker Data Wrangler, which is excellent for interactive data preparation and feature engineering but is not typically used for large-scale, scheduled batch ETL of terabytes of raw data as its primary function. Option C (incorrect) is Amazon SageMaker Processing, which can run data processing jobs, but AWS Glue is generally more optimized and cost-effective for large-scale, serverless ETL pipelines. Option D (incorrect) is Amazon Athena, which is a query service for data lakes, not an ETL service for complex transformations.', 14, 'm_14_2', 13, NULL, NULL),
  ('mock_14_all_1774923300597', 'A data scientist is preparing a dataset for a classification model. The dataset contains numerical features that need to be normalized. To prevent data leakage and ensure a robust model evaluation, the data scientist must apply feature scaling correctly after splitting the data into training and test sets. Which approach correctly applies normalization to avoid data leakage?', '["Fit the scaler on the entire dataset (training and test combined) and then transform both sets.","Fit the scaler on the training data only, then transform both the training and test data using the fitted scaler.","Fit and transform the scaler separately on the training data, and then fit and transform a new scaler separately on the test data.","Apply a fixed min-max scaling (e.g., 0-1) to all features across the entire dataset without fitting a scaler."]'::jsonb, 'mcq', '{2}'::integer[], 'Option B (correct) is to fit the scaler on the training data only, then transform both the training and test data using the fitted scaler. This approach ensures that the scaling parameters (e.g., mean and standard deviation for standardization, min and max for normalization) are learned exclusively from the training data. The test data is then transformed using these same parameters, preventing any information from the test set from ''leaking'' into the training process. Option A (incorrect) is an anti-pattern ([ap-1.2-001]) because fitting the scaler on the entire dataset (including test data) causes data leakage, as test statistics influence the training transform, leading to an overly optimistic evaluation. Option C (incorrect) would also lead to data leakage because the scaler for the test set would learn from the test data itself. Option D (incorrect) applies a fixed scaling, which might not be optimal for the data distribution and doesn''t account for the unique characteristics of the training data.', 14, 'm_14_2', 14, NULL, NULL),
  ('mock_14_all_1774923300597', 'A data science team needs to prepare a complex, multi-source dataset for machine learning. They require a visual, code-free interface to explore, clean, and engineer features, allowing them to quickly iterate on data transformations without writing extensive code. The solution should integrate with various data sources like Amazon S3, Amazon Redshift, and Amazon Athena. Which AWS service is best suited for this interactive feature engineering task?', '["AWS Glue, for its serverless ETL capabilities.","Amazon SageMaker Processing, for running custom data processing jobs.","AWS Glue DataBrew, for visual data preparation and transformation.","Amazon SageMaker Data Wrangler, for visual data preparation and feature engineering."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon SageMaker Data Wrangler. SageMaker Data Wrangler provides a visual interface to explore, prepare, and engineer features from various data sources, including Amazon S3, Amazon Redshift, and Amazon Athena. It allows data scientists to quickly build data preparation workflows and apply over 300 built-in transformations without writing code, making it ideal for interactive feature engineering. Option A (incorrect) is AWS Glue, which is a powerful serverless ETL service but primarily code-driven (PySpark/Scala) and less focused on interactive, visual data preparation. Option B (incorrect) is Amazon SageMaker Processing, which is used for running custom data processing jobs but requires writing code. Option C (incorrect) is AWS Glue DataBrew, which is also a visual data preparation tool, but SageMaker Data Wrangler is more deeply integrated with the SageMaker ecosystem for ML-specific feature engineering workflows.', 14, 'm_14_2', 15, NULL, NULL),
  ('mock_14_all_1774923300597', 'A large enterprise has multiple data science teams working on various machine learning projects. Each team develops and uses similar features (e.g., ''customer_lifetime_value'', ''average_transaction_amount'') across different models. The enterprise wants to centralize the storage, management, and sharing of these curated features to promote reuse, ensure consistency, and reduce redundant feature engineering efforts across teams. Which AWS service is designed to meet this requirement?', '["AWS Glue Data Catalog","Amazon SageMaker Feature Store","Amazon S3","Amazon Redshift"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon SageMaker Feature Store. SageMaker Feature Store is a fully managed, purpose-built repository for machine learning features. It allows data scientists to store, discover, share, and reuse curated features across multiple models and teams, ensuring consistency between training and inference and reducing redundant feature engineering efforts. Option A (incorrect) is AWS Glue Data Catalog, which stores metadata about data in a data lake but does not manage the lifecycle or serve features for ML models directly. Option C (incorrect) is Amazon S3, an object storage service, which can store features but lacks the specialized management, versioning, and serving capabilities of a feature store. Option D (incorrect) is Amazon Redshift, a data warehouse, suitable for analytical queries but not specifically designed for the operational storage and serving of ML features.', 14, 'm_14_2', 16, NULL, NULL);

