INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774923300597', 'A data science team has developed a new fraud detection model that shows excellent performance on the training dataset but significantly lower accuracy on unseen validation data, indicating overfitting. The team needs to address this issue quickly and in the MOST cost-effective manner without immediately collecting more data. Which approach should they prioritize?', '["Implement regularization techniques like L1/L2 penalties or dropout during training, combined with early stopping based on validation performance.","Increase the size and complexity of the model architecture to allow it to learn more intricate patterns from the training data.","Immediately initiate a project to collect a significantly larger and more diverse dataset to retrain the model from scratch.","Perform extensive hyperparameter tuning with a very wide search space and a limited number of trials using SageMaker Automatic Model Tuning."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective and immediate approach to combat overfitting. Regularization techniques (L1, L2, dropout) and early stopping directly address the model''s tendency to memorize training data, improving its generalization to unseen data without incurring the high cost and time of data collection. Option B (incorrect) would likely exacerbate the overfitting problem by giving the model more capacity to memorize noise in the training data. Option C (incorrect) represents an anti-pattern ([ap-2.3-001]) as collecting more data is often a time-consuming and expensive process, and should be considered after simpler regularization methods have been attempted. Option D (incorrect) represents an anti-pattern ([ap-2.2-001]) because a very wide search space with limited trials is inefficient and unlikely to find optimal hyperparameters, wasting compute resources.', 15, 'm_15_3', 1, NULL, NULL),
  ('mock_14_all_1774923300597', 'A machine learning engineer is training a complex deep learning model on Amazon SageMaker that takes several hours to complete. They want to proactively identify potential issues such as vanishing/exploding gradients or overfitting during the training process to prevent wasted compute time and resources. Which SageMaker feature should be used to achieve this with MINIMAL operational overhead?', '["Utilize SageMaker Debugger to monitor training job metrics and detect anomalies in real-time, automatically stopping the job if issues are found.","Manually inspect Amazon CloudWatch logs generated by the training job every 15 minutes for error messages and performance degradation.","Implement custom logging within the training script to push detailed metric data to Amazon S3, then analyze it offline after the job completes.","Set up a separate AWS Lambda function to periodically query the training job''s status and send notifications if it runs longer than expected."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages SageMaker Debugger, which is specifically designed for real-time monitoring of training jobs. It can detect common issues like vanishing/exploding gradients, overfitting, and other anomalies, and can even be configured to automatically stop jobs, minimizing wasted compute resources with minimal operational overhead. Option B (incorrect) involves manual inspection, which is reactive, time-consuming, and prone to human error, failing the ''minimal operational overhead'' constraint. Option C (incorrect) requires custom implementation and offline analysis, which is not real-time and adds development and operational overhead. Option D (incorrect) creates additional operational overhead by requiring a separate Lambda function and custom logic, which is less integrated and efficient than SageMaker Debugger.', 15, 'm_15_3', 2, NULL, NULL),
  ('mock_14_all_1774923300597', 'A financial institution is developing a credit risk assessment model using Amazon SageMaker. Due to regulatory requirements and ethical concerns, they must ensure that the model does not exhibit unintended bias against specific demographic groups and that its predictions are explainable. Which SageMaker service should the MLOps engineer use for post-training analysis to meet these requirements?', '["Amazon SageMaker Experiments to track different model versions and their performance metrics during development.","Amazon SageMaker Clarify to detect potential bias in the model and provide feature attribution for explainability.","Amazon SageMaker Debugger to monitor the training process for issues like overfitting or underfitting.","Amazon SageMaker Automatic Model Tuning to optimize hyperparameters for improved model accuracy."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes Amazon SageMaker Clarify, which is specifically designed for detecting potential bias in machine learning models and providing feature attribution for explainability. This directly addresses the regulatory and ethical requirements for fairness and transparency in the credit risk assessment model. Option A (incorrect) is used for organizing and comparing different training runs, not for bias detection or explainability analysis. Option C (incorrect) focuses on identifying issues during the training process, such as gradient problems or overfitting, rather than post-training bias or explainability. Option D (incorrect) is used to find the best set of hyperparameters to improve model performance, which is unrelated to bias detection or model explainability.', 15, 'm_15_3', 3, NULL, NULL),
  ('mock_14_all_1774923300597', 'A data scientist has built a binary classification model on Amazon SageMaker to predict customer churn. The dataset is highly imbalanced, with only 5% of customers churning. The business objective is to identify as many churning customers as possible to offer retention incentives, even if it means contacting some non-churning customers. Which evaluation metric is MOST appropriate to assess the model''s effectiveness for this specific business objective?', '["Accuracy, as it provides a general measure of correct predictions across all classes.","Mean Absolute Error (MAE), which measures the average magnitude of errors in predictions.","Recall (Sensitivity), as it quantifies the proportion of actual positive churners that were correctly identified by the model.","Root Mean Squared Error (RMSE), which is commonly used for regression problems to measure prediction error."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate metric. Recall (also known as Sensitivity) measures the proportion of actual positive cases (churners) that were correctly identified by the model. In an imbalanced dataset where the goal is to identify as many minority class instances (churners) as possible, maximizing recall is crucial, even if it leads to a higher number of false positives. Option A (incorrect) is misleading for imbalanced datasets because a model can achieve high accuracy by simply predicting the majority class, failing to identify the minority class. Option B (incorrect) and Option D (incorrect) are regression metrics and are not suitable for evaluating a binary classification model.', 15, 'm_15_3', 4, NULL, NULL),
  ('mock_14_all_1774923300597', 'A machine learning model trained on Amazon SageMaker consistently performs poorly on both the training dataset and the validation dataset. The model struggles to capture the underlying patterns in the data, resulting in high errors across the board. The data science team needs to identify the most likely cause of this behavior. What is the primary issue the model is exhibiting?', '["Overfitting, where the model has learned the training data too well, including noise, and fails to generalize.","Underfitting, where the model is too simple or has not been trained sufficiently to capture the complexity of the data.","Data leakage, where information from the test set has inadvertently influenced the training process.","Bias in the dataset, leading to unfair predictions for certain groups, but not necessarily poor overall performance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes underfitting. When a model performs poorly on both training and validation data, it indicates that the model is too simple or has not been adequately trained to learn the underlying patterns, thus failing to capture the complexity of the data. Option A (incorrect) describes overfitting, which would typically manifest as high performance on training data but poor performance on validation data. Option C (incorrect) refers to data leakage, which would typically lead to overly optimistic validation/test scores that don''t reflect real-world performance, not necessarily poor performance on both sets. Option D (incorrect) describes a different problem related to fairness and ethical considerations, which might or might not coincide with poor overall performance.', 15, 'm_15_3', 5, NULL, NULL),
  ('mock_14_all_1774923300597', 'A healthcare provider uses a machine learning model to classify patient scans as ''diseased'' or ''healthy''. The medical team needs to understand the types of errors the model is making, specifically distinguishing between false positives (healthy patients misclassified as diseased) and false negatives (diseased patients misclassified as healthy). Which evaluation tool provides this detailed breakdown of correct and incorrect classifications?', '["An AUC-ROC curve, which illustrates the trade-off between true positive rate and false positive rate at various thresholds.","A confusion matrix, which displays the counts of true positives, true negatives, false positives, and false negatives.","A precision-recall curve, which shows the trade-off between precision and recall for different thresholds.","A histogram of prediction probabilities, which visualizes the distribution of model outputs."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is a confusion matrix, which is the most direct and comprehensive tool for understanding the specific types of errors a classification model makes. It explicitly shows the counts of true positives, true negatives, false positives, and false negatives, allowing the medical team to directly see how many healthy patients were misclassified as diseased (false positives) and how many diseased patients were missed (false negatives). Option A (incorrect) and Option C (incorrect) are useful for evaluating model performance across different thresholds but do not directly provide the raw counts of each error type. Option D (incorrect) helps understand the model''s confidence but not the specific error categories.', 15, 'm_15_3', 6, NULL, NULL);

