-- Module: m_15_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774923300597', 'An e-commerce company wants to predict future sales for thousands of individual products over the next six months. The sales data exhibits complex seasonality, trends, and occasional promotions. The data science team has limited time and resources and needs a robust, scalable solution for time series forecasting. Which Amazon SageMaker built-in algorithm is BEST suited for this task?', '["Amazon SageMaker XGBoost, which is highly effective for tabular data and gradient boosting.","Amazon SageMaker Linear Learner, ideal for large-scale linear regression and classification problems.","Amazon SageMaker DeepAR, which uses recurrent neural networks to forecast time series data.","Amazon SageMaker k-means, an unsupervised learning algorithm for clustering data points."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker DeepAR, which is specifically designed for time series forecasting. It uses recurrent neural networks (RNNs) to model complex dependencies and patterns in time series data, making it highly effective for problems with seasonality, trends, and multiple related time series, such as predicting sales for thousands of products. Option A (incorrect) is primarily for tabular data classification and regression, not specialized for time series. Option B (incorrect) is for linear models, which are generally less effective at capturing complex time series patterns. Option D (incorrect) is an unsupervised clustering algorithm, unrelated to forecasting.', 15, 'm_15_1', 7, NULL, NULL),
  ('mock_14_all_1774923300597', 'A large customer support center receives millions of customer feedback comments daily. The company wants to automatically classify these comments into predefined categories (e.g., ''billing issue'', ''technical support'', ''feature request'') to route them to the correct department. The solution needs to be highly scalable, cost-effective, and efficient for large volumes of text data. Which Amazon SageMaker built-in algorithm should be chosen?', '["Amazon SageMaker k-NN, suitable for classification and regression based on nearest neighbors.","Amazon SageMaker Object Detection, designed for identifying objects within images.","Amazon SageMaker BlazingText, optimized for highly efficient text classification and word embeddings.","Amazon SageMaker PCA, an unsupervised algorithm for dimensionality reduction in high-dimensional data."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker BlazingText, which is specifically optimized for efficient and scalable text classification tasks, making it ideal for processing millions of customer feedback comments. It can handle large datasets and provides fast training and inference for text-based problems. Option A (incorrect) is a general-purpose classification algorithm but not optimized for text data at this scale. Option B (incorrect) is for image analysis, not text. Option D (incorrect) is for dimensionality reduction, not classification. Using a custom algorithm instead of BlazingText would be an anti-pattern ([ap-2.1-001]) as BlazingText is optimized for distributed training and scale on AWS infrastructure for text tasks.', 15, 'm_15_1', 8, NULL, NULL),
  ('mock_14_all_1774923300597', 'A small startup is developing an application that needs to classify images of different plant species. They have a limited dataset and no in-house machine learning experts, but they need to quickly deploy a high-performing model. They want to leverage pre-trained models and minimize development effort. Which SageMaker feature should they use?', '["SageMaker JumpStart, which provides pre-built solutions and pre-trained models for common use cases, including image classification.","SageMaker Training Jobs with a custom PyTorch script, allowing full control over the model architecture and training process.","SageMaker Automatic Model Tuning (HPO) to find the optimal hyperparameters for a custom-built image classification model.","SageMaker Debugger to analyze the training process of a custom model for issues like overfitting or vanishing gradients."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is SageMaker JumpStart, which provides a collection of pre-trained models and pre-built solutions for various tasks, including image classification. It enables users with limited ML expertise to quickly deploy high-performing models, often leveraging transfer learning, directly addressing the startup''s needs for rapid deployment and minimal development effort. Option B (incorrect) requires significant ML expertise and development effort to build and optimize a custom PyTorch model. Option C (incorrect) is for optimizing hyperparameters of an existing model, not for quickly deploying a pre-trained solution. Option D (incorrect) is for debugging training jobs, which comes after model selection and initial setup.', 15, 'm_15_1', 9, NULL, NULL),
  ('mock_14_all_1774923300597', 'A retail company wants to predict customer churn based on their purchasing history, demographic information, and website interaction data. This data is primarily tabular and contains a mix of numerical and categorical features. The business objective is to achieve the HIGHEST possible predictive accuracy for identifying at-risk customers. Which Amazon SageMaker built-in algorithm is generally known for its high performance on structured, tabular datasets?', '["Amazon SageMaker Linear Learner, which is efficient for large-scale linear models.","Amazon SageMaker XGBoost, a powerful gradient boosting algorithm known for high accuracy on tabular data.","Amazon SageMaker k-means, an unsupervised clustering algorithm for segmenting data.","Amazon SageMaker BlazingText, optimized for text classification and word embeddings."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon SageMaker XGBoost. XGBoost is a highly efficient and powerful gradient boosting algorithm that consistently delivers state-of-the-art performance on structured, tabular datasets, making it an excellent choice for predicting customer churn where high predictive accuracy is the primary objective. Option A (incorrect) is for linear models, which may not capture complex non-linear relationships as effectively as XGBoost. Option C (incorrect) is an unsupervised clustering algorithm, not suitable for a supervised prediction task like churn. Option D (incorrect) is for text data, which is not the primary data type for this problem.', 15, 'm_15_1', 10, NULL, NULL),
  ('mock_14_all_1774923300597', 'A marketing department wants to understand distinct customer segments within their large customer base to tailor personalized campaigns. They have extensive customer data, including demographics, purchase history, and browsing behavior, but no predefined labels for segments. They need to discover natural groupings in the data. Which Amazon SageMaker built-in algorithm is suitable for this unsupervised learning task?', '["Amazon SageMaker Linear Learner, for supervised regression or classification.","Amazon SageMaker XGBoost, for supervised classification or regression on tabular data.","Amazon SageMaker k-means, for unsupervised clustering to identify natural groupings in data.","Amazon SageMaker Object Detection, for identifying objects within images."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker k-means. k-means is a popular unsupervised learning algorithm used for clustering, which is precisely the task of identifying natural groupings or segments within a dataset without prior labels. This directly addresses the marketing department''s need to discover customer segments. Option A (incorrect) and Option B (incorrect) are supervised learning algorithms that require labeled data for training. Option D (incorrect) is for computer vision tasks, not customer segmentation.', 15, 'm_15_1', 11, NULL, NULL),
  ('mock_14_all_1774923300597', 'A manufacturing company wants to automate quality control by identifying specific defects (e.g., scratches, dents, misalignments) on product images captured from their assembly line. They need a solution that can not only classify an image as ''defective'' but also precisely locate and identify multiple types of defects within a single image. Which Amazon SageMaker built-in algorithm is BEST suited for this requirement?', '["Amazon SageMaker Image Classification, which assigns a single label to an entire image.","Amazon SageMaker BlazingText, designed for text classification and word embeddings.","Amazon SageMaker Object Detection, which identifies and localizes multiple objects within an image.","Amazon SageMaker PCA, an unsupervised algorithm for dimensionality reduction."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker Object Detection. This algorithm is specifically designed to identify and localize multiple objects (in this case, different types of defects) within an image by drawing bounding boxes around them and assigning a label. This directly meets the requirement to not only classify but also precisely locate and identify multiple defects. Option A (incorrect) would only classify the entire image as ''defective'' or ''not defective'' but would not locate specific defects. Option B (incorrect) is for text analysis. Option D (incorrect) is for dimensionality reduction, not object identification in images.', 15, 'm_15_1', 12, NULL, NULL);

