-- Module: m_15_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_14_all_1774923300597', 'A data science team is training a large deep learning model on Amazon SageMaker. The training process is computationally intensive and can take several days. The team needs to MINIMIZE training costs while ensuring that the job can recover from interruptions. Which SageMaker training feature should they leverage?', '["Amazon SageMaker Managed Spot Training with checkpointing enabled.","On-Demand Amazon EC2 instances with a custom fault-tolerance script.","SageMaker Training Jobs on Reserved Instances for predictable cost.","Distributed training using data parallelism across multiple GPU instances without checkpointing."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SageMaker Managed Spot Training with checkpointing enabled. SageMaker Managed Spot Training uses EC2 Spot Instances, which can significantly reduce training costs (up to 90%) compared to On-Demand instances. With checkpointing, the training job can save its state periodically and resume from the last checkpoint if interrupted, ensuring fault tolerance and minimizing lost work, directly addressing the requirement to minimize costs while recovering from interruptions. Option B (incorrect) would be significantly more expensive than Spot Instances and requires custom effort for fault tolerance. Option C (incorrect) provides predictable costs but does not offer the cost savings of Spot Instances for long-running, interruptible workloads. Option D (incorrect) would not allow recovery from interruptions without checkpointing, leading to wasted compute time and increased costs if the job fails, representing an anti-pattern ([ap-2.2-002]).', 15, 'm_15_2', 13, NULL, NULL),
  ('mock_14_all_1774923300597', 'A machine learning engineer is developing a new model on Amazon SageMaker and needs to find the optimal combination of hyperparameters to achieve the best model performance. The search space for these hyperparameters is large, and manual tuning is time-consuming and inefficient. The engineer wants to automate this process to quickly converge on a high-performing model. Which SageMaker feature should be used for this task?', '["SageMaker Automatic Model Tuning (HPO) using Bayesian optimization.","SageMaker Training Jobs with a fixed set of hyperparameters and manual adjustments.","SageMaker Debugger to identify the best hyperparameters by analyzing training metrics.","SageMaker Experiments to track and compare the performance of different models with fixed hyperparameters."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is SageMaker Automatic Model Tuning (HPO) using Bayesian optimization. HPO automates the process of finding the best hyperparameters. Bayesian optimization is an efficient search strategy that intelligently explores the hyperparameter space, converging faster to optimal configurations compared to random or grid search, which is ideal for large search spaces and quickly achieving high performance. Option B (incorrect) is a manual and inefficient approach, especially for a large search space. Option C (incorrect) is for analyzing training job issues, not for hyperparameter optimization. Option D (incorrect) is for tracking and comparing experiments, which is complementary to HPO but does not automate the tuning process itself. Running HPO with a too wide search space and few trials without intelligent strategies like Bayesian optimization would be an anti-pattern ([ap-2.2-001]).', 15, 'm_15_2', 14, NULL, NULL),
  ('mock_14_all_1774923300597', 'A data science team is actively developing multiple machine learning models for various business problems. They frequently run numerous training jobs with different algorithms, datasets, and hyperparameter configurations. The team needs a centralized way to organize, compare, and reproduce these experiments efficiently to track progress and share results. Which Amazon SageMaker feature is designed for this purpose?', '["Amazon SageMaker Debugger, to analyze training job issues in real-time.","Amazon SageMaker Clarify, for bias detection and model explainability.","Amazon SageMaker Experiments, for tracking, comparing, and reproducing ML experiments.","Amazon SageMaker Automatic Model Tuning, for optimizing hyperparameters."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker Experiments. This service is specifically designed to help data science teams organize, track, compare, and reproduce all aspects of their machine learning experiments, including training jobs, datasets, algorithms, and hyperparameter configurations. This directly addresses the need for a centralized system to manage and share experiment results. Option A (incorrect) is for monitoring and debugging training jobs for issues like overfitting or vanishing gradients. Option B (incorrect) is for analyzing model bias and explainability post-training. Option D (incorrect) is for automating the search for optimal hyperparameters, not for general experiment tracking and comparison.', 15, 'm_15_2', 15, NULL, NULL),
  ('mock_14_all_1774923300597', 'A company is training a very large deep learning model on Amazon SageMaker using a dataset that is too big to fit into the memory of a single GPU instance. The training process needs to be scaled efficiently across multiple instances to complete within a reasonable timeframe. Which distributed training strategy is commonly used in SageMaker for handling such large datasets?', '["Model parallelism, where different layers of the model are distributed across multiple GPUs.","Data parallelism, where the dataset is split across multiple instances, and each instance trains a replica of the model.","Pipeline parallelism, which involves breaking down the model into stages and processing data through these stages sequentially on different devices.","Manual sharding, where the dataset is manually partitioned and uploaded to separate Amazon S3 buckets for each instance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is data parallelism. When the dataset is too large to fit into a single GPU''s memory, data parallelism is the common strategy. The dataset is split into smaller batches, and each training instance processes a different batch using its own replica of the model. Gradients are then aggregated and synchronized across instances. This efficiently scales training for large datasets. Option A (incorrect) is used when the model itself is too large to fit on a single GPU, distributing model layers, not primarily for large datasets. Option C (incorrect) is a specialized form of model parallelism. Option D (incorrect) would be a manual and inefficient approach, increasing operational overhead compared to SageMaker''s built-in distributed training capabilities.', 15, 'm_15_2', 16, NULL, NULL),
  ('mock_14_all_1774923300597', 'A machine learning engineer is setting up an Amazon SageMaker Training Job for a large-scale image recognition model. This model requires significant computational power, specifically high-performance GPUs, to train efficiently. The primary goal is to optimize the training process for speed and performance. Which type of Amazon EC2 instance family should be selected for the SageMaker Training Job?', '["M5 instances, which are general-purpose instances suitable for a wide range of workloads.","T3 instances, which are burstable performance instances ideal for workloads with moderate CPU usage.","P3 or P4 instances, which are GPU-accelerated instances specifically designed for deep learning and high-performance computing.","R5 instances, which are memory-optimized instances suitable for memory-intensive applications."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) identifies P3 or P4 instances. These are Amazon EC2 GPU-accelerated instances specifically designed for deep learning training and other high-performance computing workloads. They provide the necessary computational power and high-performance GPUs required for large-scale image recognition models, optimizing the training process for speed and performance. Option A (incorrect) and Option B (incorrect) are general-purpose or burstable instances, lacking the dedicated GPU resources needed for intensive deep learning. Option D (incorrect) is memory-optimized, not compute-optimized for GPU workloads.', 15, 'm_15_2', 17, NULL, NULL);

